lb_a_sema_prelude_Prelude_arr20 lb_sema_prelude_modules = ((lb_a_sema_prelude_Prelude_arr20){{((lb_sema_prelude_Prelude){.name = ((lb_str){"platform", 8}), .text = ((lb_str){"## The target of the build, as constants (\302\24719.5): generated by the compiler from\n## `--target` (`Target.module_text`); this placeholder is what the prelude embeds and the\n## checker replaces. `os` re-exports these for programs; the standard library branches\n## on them directly.\npub let name: str = \"arm64-macos\"\npub let macos: bool = true\npub let linux: bool = false\npub let windows: bool = false\npub let posix: bool = true\npub let arm64: bool = true\npub let x86_64: bool = false\npub let pointer_bits: u32 = 64\n## The instruction-set level the program is compiled for (\302\24719.5): 1 is the family's baseline.\npub let cpu_level: u32 = 1\n", 635})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"c", 1}), .text = ((lb_str){"## C's types live here (base.md \302\2475.2); the checker supplies them, since their widths are the\n## target's: `c.int` and the other fixed-width ones are Base types by another name, `c.char`,\n## `c.long`, `c.ulong`, and `c.wchar` are distinct, `c.va_list` is opaque, `c.str` is C text.\n\nimport platform\n\nextern func mac_errno as \"__error\"() -> i32*\nextern func linux_errno as \"__errno_location\"() -> i32*\n\n## The calling thread's `errno`: the C library's account of its last failure.\npub func errno() -> i32:\n    if platform.macos:\n        return *mac_errno()\n    return *linux_errno()\n\n## Set the calling thread's errno. Clear it immediately before C calls such as\n## readdir whose null result can mean either normal completion or failure.\npub func set_errno(value: i32):\n    if platform.macos:\n        *mac_errno() = value\n    else:\n        *linux_errno() = value\n\n## `EINTR`: a call a signal interrupted, to be made again. The same number on both hosts.\npub let interrupted: i32 = 4\n\n## The C standard streams; the backend supplies them.\npub func stdin() -> void*:\n    trap(\"supplied by the backend\")\npub func stdout() -> void*:\n    trap(\"supplied by the backend\")\npub func stderr() -> void*:\n    trap(\"supplied by the backend\")\n", 1228})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"core", 4}), .text = ((lb_str){"import c\nextern func write(descriptor: i32, buffer: const void*, count: usize) -> isize\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func malloc(size: usize) -> void*\?\nextern func memcpy(target: void*, source: const void*, count: usize) -> void*\nextern func memcmp(a: const void*, b: const void*, count: usize) -> i32\nextern func strlen(text: c.str) -> usize\nextern func snprintf(buffer: void*, size: usize, format: c.str, ...) -> i32\n\n## Stop the program with its reason on stderr (\302\2478.7).\npub func trap(message: c.str) -> never:\n    let prefix = \"trap: \"\n    discard(write(2, prefix.bytes.data, prefix.length))\n    discard(write(2, (const void*)message, strlen(message)))\n    let newline = \"\\n\"\n    discard(write(2, newline.bytes.data, 1))\n    c_exit(1)\n\n## `trap: file:line:column: message`: a trap naming the statement it stopped at (\302\24711.5).\npub func trap_at(position: c.str, message: c.str) -> never:\n    let prefix = \"trap: \"\n    discard(write(2, prefix.bytes.data, prefix.length))\n    discard(write(2, (const void*)position, strlen(position)))\n    let sep = \": \"\n    discard(write(2, sep.bytes.data, 2))\n    discard(write(2, (const void*)message, strlen(message)))\n    let newline = \"\\n\"\n    discard(write(2, newline.bytes.data, 1))\n    c_exit(1)\n\n## `trap: file:line:column: message: detail`, for an `assert` whose message is computed.\npub func trap_two_at(position: c.str, message: c.str, detail: c.str) -> never:\n    let prefix = \"trap: \"\n    discard(write(2, prefix.bytes.data, prefix.length))\n    discard(write(2, (const void*)position, strlen(position)))\n    let sep = \": \"\n    discard(write(2, sep.bytes.data, 2))\n    discard(write(2, (const void*)message, strlen(message)))\n    discard(write(2, sep.bytes.data, 2))\n    discard(write(2, (const void*)detail, strlen(detail)))\n    let newline = \"\\n\"\n    discard(write(2, newline.bytes.data, 1))\n    c_exit(1)\n\n## `trap: message: detail`, for an `assert` whose message is computed (\302\24711.6).\npub func trap_two(message: c.str, detail: c.str) -> never:\n    let prefix = \"trap: \"\n    discard(write(2, prefix.bytes.data, prefix.length))\n    discard(write(2, (const void*)message, strlen(message)))\n    let sep = \": \"\n    discard(write(2, sep.bytes.data, 2))\n    discard(write(2, (const void*)detail, strlen(detail)))\n    let newline = \"\\n\"\n    discard(write(2, newline.bytes.data, 1))\n    c_exit(1)\n\n## The buffer `format` and f\"...\" fill: the bytes, their capacity, and the count used.\npub struct FormatBuffer:\n    pub var data: u8*\n    pub var capacity: usize\n    pub var used: usize\n\n## Append `count` bytes; 1 when they do not fit, and the buffer is then over capacity.\npub func format_put(b: FormatBuffer*, text: const void*\?, count: usize) -> i32:\n    if count > b.capacity or b.used > b.capacity - count:\n        b.used = b.capacity +% 1\n        return 1\n    if let source = text:\n        if count > 0:\n            discard(memcpy(&b.data[b.used], source, count))\n    b.used += count\n    return 0\n\npub func format_u64(b: FormatBuffer*, value: u64) -> i32:\n    var digits: u8[24] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[23] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        digits[24 - n] = (u8)(48 + v % 10)\n        v = v // 10\n    return format_put(b, &digits[24 - n], n)\n\npub func format_i64(b: FormatBuffer*, value: i64) -> i32:\n    if value < 0:\n        let minus = \"-\"\n        if format_put(b, minus.bytes.data, 1) != 0:\n            return 1\n        return format_u64(b, 0 -% (u64)value)\n    return format_u64(b, (u64)value)\n\n## `%g`, as the C library spells it, so both backends print one text.\npub func format_f64(b: FormatBuffer*, value: f64) -> i32:\n    var text: u8[64] = ---\n    let n = snprintf((void*)&text[0], 64, \"%g\", value)\n    if n < 0:\n        return 1\n    return format_put(b, &text[0], (usize)n)\n\npub func format_bool(b: FormatBuffer*, value: bool) -> i32:\n    let word = \"true\" if value else \"false\"\n    return format_put(b, word.bytes.data, word.length)\n\n## A `char` displays as itself, in UTF-8 (\302\24714.4).\npub func format_char(b: FormatBuffer*, value: char) -> i32:\n    let cp = u32(value)\n    var out: u8[4]\n    var n: usize = 0\n    if cp < 0x80:\n        out[0] = u8(cp)\n        n = 1\n    elif cp < 0x800:\n        out[0] = u8(0xC0 | (cp >> 6))\n        out[1] = u8(0x80 | (cp & 0x3F))\n        n = 2\n    elif cp < 0x10000:\n        out[0] = u8(0xE0 | (cp >> 12))\n        out[1] = u8(0x80 | ((cp >> 6) & 0x3F))\n        out[2] = u8(0x80 | (cp & 0x3F))\n        n = 3\n    else:\n        out[0] = u8(0xF0 | (cp >> 18))\n        out[1] = u8(0x80 | ((cp >> 12) & 0x3F))\n        out[2] = u8(0x80 | ((cp >> 6) & 0x3F))\n        out[3] = u8(0x80 | (cp & 0x3F))\n        n = 4\n    return format_put(b, (const void*)&out, n)\n\n## The text so far, NUL-terminated when there is room.\npub func format_finish(b: FormatBuffer*) -> str:\n    if b.used < b.capacity:\n        b.data[b.used] = 0\n    if b.used > b.capacity:\n        return \"\"\n    return (str)u8[](b.data, b.used)\n\n## `hex`, `bin`, and `pad` return text in one of four rotating thread-local slots.\nlocal var show_bytes: u8[1024]\nlocal var show_next: u32\n\nfunc show_take(source: const u8*, count: usize) -> str:\n    let slot = (usize)(show_next & 3) * 256\n    show_next = show_next +% 1\n    var n = count\n    if n > 255:\n        n = 255\n    if n > 0:\n        discard(memcpy(&show_bytes[slot], source, n))\n    show_bytes[slot + n] = 0\n    return (str)show_bytes[slot..<slot + n]\n\npub func show_hex(value: u64) -> str:\n    var digits: u8[16] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[15] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        let d = (u8)(v & 15)\n        digits[16 - n] = d + 48 if d < 10 else d + 87\n        v = v >> 4\n    return show_take(&digits[16 - n], n)\n\npub func show_bin(value: u64) -> str:\n    var digits: u8[64] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[63] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        digits[64 - n] = 48 + (u8)(v & 1)\n        v = v >> 1\n    return show_take(&digits[64 - n], n)\n\npub func show_pad(inner: str, width: usize) -> str:\n    var n = inner.length\n    if n >= width:\n        return show_take(inner.bytes.data, n)\n    var text: u8[256] = ---\n    var pad = width - n\n    if width > 255:\n        if n > 255:\n            n = 255\n        pad = 255 - n\n    for i in 0..<pad:\n        text[i] = 32\n    if n > 0:\n        discard(memcpy(&text[pad], inner.bytes.data, n))\n    return show_take(&text[0], pad + n)\n\n## The startup shim's pieces: the argument vector as `str[]` (checked) or `c.str[]`.\npub func arguments(count: i32, vector: c.str*) -> str[]:\n    let n = (usize)count\n    let block = malloc((n if n > 0 else 1) * sizeof(str)) else trap(\"memory.exhausted\")\n    let items = (str*)block\n    var i: usize = 0\n    while i < n:\n        let text = (str)vector[i]\n        if not utf8_ok(text.bytes.data, text.length):\n            trap(\"invalid_utf8\")\n        items[i] = text\n        i += 1\n    return str[](items, n)\n\npub func raw_arguments(count: i32, vector: c.str*) -> c.str[]:\n    return c.str[](vector, (usize)count)\n\n## A failed `main`: its error on stderr, exit status 1.\npub func main_failed(code: i32, message: str) -> i32:\n    var bytes: u8[1024] = ---\n    let line = format(bytes, f\"error {code}: {message}\\n\") catch:\n        return 1\n    discard(write(2, line.bytes.data, line.length))\n    return 1\n\n## The test runner's report line and its summary.\npub func test_report(name: str, failed: bool, message: str):\n    var bytes: u8[1024] = ---\n    let line = format(bytes, f\"FAIL  {name}\\n      error: {message}\\n\" if failed else f\"ok    {name}\\n\") catch:\n        return\n    discard(write(1, line.bytes.data, line.length))\n\npub func test_summary(total: i32, failed: i32) -> i32:\n    var bytes: u8[64] = ---\n    let line = format(bytes, f\"{total - failed} passed\\n\") catch:\n        return 1\n    discard(write(1, line.bytes.data, line.length))\n    return 0 if failed == 0 else 1\n\n## `print`: the text and a newline on stdout; `answer()` programs print their number.\npub func print_str(text: str):\n    discard(write(1, text.bytes.data, text.length))\n    let newline = \"\\n\"\n    discard(write(1, newline.bytes.data, 1))\n\npub func print_i64(value: i64):\n    var bytes: u8[32] = ---\n    let all: u8[] = bytes\n    var b = FormatBuffer(data = all.data, capacity = 32, used = 0)\n    discard(format_i64(&b, value))\n    discard(write(1, all.data, b.used))\n    let newline = \"\\n\"\n    discard(write(1, newline.bytes.data, 1))\n\n## Ordering of text: bytewise, then by length (\302\2477.4).\npub func str_compare(a: str, b: str) -> i32:\n    let n = a.length if a.length < b.length else b.length\n    var order: i32 = 0\n    if n > 0:\n        order = memcmp(a.bytes.data, b.bytes.data, n)\n    if order != 0:\n        return -1 if order < 0 else 1\n    if a.length < b.length:\n        return -1\n    return 1 if a.length > b.length else 0\n\n## The scalar starting at byte `index` of `count` bytes of valid UTF-8, its width left in\n## `width`: what `for character in text` steps by (\302\2475.5).\npub func utf8_scalar(text: const u8*, count: usize, index: usize, width: usize*) -> char:\n    let byte = text[index]\n    var w: usize = 1\n    var cp: u32 = (u32)byte\n    if byte >= 240:\n        w = 4\n        cp = (u32)(byte & 7)\n    elif byte >= 224:\n        w = 3\n        cp = (u32)(byte & 15)\n    elif byte >= 192:\n        w = 2\n        cp = (u32)(byte & 31)\n    if index + w > count:\n        w = count - index\n    var k: usize = 1\n    while k < w:\n        cp = (cp << 6) | (u32)(text[index + k] & 63)\n        k += 1\n    *width = w\n    return char(cp)\n\n## Whether `count` bytes are well-formed UTF-8: no overlong forms, no surrogates, nothing past U+10FFFF.\npub func utf8_ok(text: const u8*\?, count: usize) -> bool:\n    let s = text else return count == 0\n    var i: usize = 0\n    while i < count:\n        let byte = s[i]\n        var w: usize = 1\n        var cp: u32 = 0\n        if byte < 128:\n            cp = (u32)byte\n        elif (byte & 224) == 192:\n            w = 2\n            cp = (u32)(byte & 31)\n        elif (byte & 240) == 224:\n            w = 3\n            cp = (u32)(byte & 15)\n        elif (byte & 248) == 240:\n            w = 4\n            cp = (u32)(byte & 7)\n        else:\n            return false\n        if i + w > count:\n            return false\n        var k: usize = 1\n        while k < w:\n            let x = s[i + k]\n            if (x & 192) != 128:\n                return false\n            cp = (cp << 6) | (u32)(x & 63)\n            k += 1\n        if w == 2 and cp < 128:\n            return false\n        if w == 3 and cp < 2048:\n            return false\n        if w == 4 and cp < 65536:\n            return false\n        if cp >= 55296 and cp <= 57343:\n            return false\n        if cp > 1114111:\n            return false\n        i += w\n    return true\n\n## `hash`: a per-process seed and a multiplicative mixer (\302\2477.4).\nvar hash_seed_value: u64\nvar hash_seeded: bool\n\npub func hash_seed() -> u64:\n    if not hash_seeded:\n        hash_seed_value = 11400714819323198485 ^ (u64)(usize)&hash_seed_value\n        hash_seeded = true\n    return hash_seed_value\n\npub func hash_mix(h: u64, x: u64) -> u64:\n    var r = h ^ x\n    r = r *% 11400714819323198485\n    r = r ^ (r >> 32)\n    return r\n\npub func hash_bytes(h: u64, data: const void*\?, count: usize) -> u64:\n    var r = h\n    if let p = data:\n        let bytes = (const u8*)p\n        var i: usize = 0\n        while i < count:\n            r = hash_mix(r, (u64)bytes[i])\n            i += 1\n    return hash_mix(r, (u64)count)\n\n## Integer conversions between widths: `bits` of `value` as a 64-bit word.\nfunc mask_of(bits: i32) -> u64:\n    if bits >= 64:\n        return 18446744073709551615\n    return (1 << (u64)bits) - 1\n\nfunc sign_extend(value: i64, bits: i32) -> i64:\n    if bits >= 64:\n        return value\n    let m = mask_of(bits)\n    let x = (u64)value & m\n    if (x & (1 << (u64)(bits - 1))) != 0:\n        return (i64)(x | ~m)\n    return (i64)x\n\nfunc zero_extend(value: u64, bits: i32) -> u64:\n    return value & mask_of(bits)\n\nfunc signed_min(bits: i32) -> i64:\n    if bits >= 64:\n        return -9223372036854775807 - 1\n    return 0 -% (1 << (i64)(bits - 1))\n\nfunc signed_max(bits: i32) -> i64:\n    if bits >= 64:\n        return 9223372036854775807\n    return (1 << (i64)(bits - 1)) - 1\n\nfunc fits_signed(value: i64, bits: i32) -> bool:\n    return value >= signed_min(bits) and value <= signed_max(bits)\n\nfunc fits_unsigned(value: u64, bits: i32) -> bool:\n    return value <= mask_of(bits)\n\n## `T(x)` between integers (`mode` 0, checked) and `(T)x` (`mode` 1, truncating).\npub func conv_s(value: i64, from_bits: i32, from_signed: i32, to_bits: i32, to_signed: i32, mode: i32) -> i64:\n    var a = value\n    if from_signed != 0:\n        a = sign_extend(a, from_bits)\n    else:\n        a = (i64)zero_extend((u64)a, from_bits)\n    if mode == 0:\n        if to_signed != 0:\n            if not fits_signed(a, to_bits):\n                trap(\"integer conversion out of range\")\n            return a\n        if a < 0 or not fits_unsigned((u64)a, to_bits):\n            trap(\"integer conversion out of range\")\n        return a\n    let bits = (u64)a & mask_of(to_bits)\n    if to_signed != 0:\n        return sign_extend((i64)bits, to_bits)\n    return (i64)bits\n\npub func conv_u(value: u64, from_bits: i32, from_signed: i32, to_bits: i32, to_signed: i32, mode: i32) -> u64:\n    let s = sign_extend((i64)value, from_bits) if from_signed != 0 else (i64)zero_extend(value, from_bits)\n    if mode == 0:\n        if to_signed != 0:\n            if not fits_signed(s, to_bits):\n                trap(\"integer conversion out of range\")\n            return (u64)s\n        if s < 0 or not fits_unsigned((u64)s, to_bits):\n            trap(\"integer conversion out of range\")\n        return (u64)s\n    return zero_extend((u64)s, to_bits)\n\nfunc is_finite(value: f64) -> bool:\n    return value - value == 0.0\n\n## Float to integer: checked (`mode` 0) or saturating (`mode` 1); the cast inside is the target's own.\npub func f_to_s(value: f64, bits: i32, mode: i32) -> i64:\n    let low = (f64)signed_min(bits)\n    let high = (f64)signed_max(bits)\n    if mode == 0:\n        if not is_finite(value) or value < low or value > high:\n            trap(\"integer conversion out of range\")\n        return (i64)value\n    if value != value:\n        return 0\n    if value <= low:\n        return signed_min(bits)\n    if value >= high:\n        return signed_max(bits)\n    return (i64)value\n\npub func f_to_u(value: f64, bits: i32, mode: i32) -> u64:\n    let high = (f64)mask_of(bits)\n    if mode == 0:\n        if not is_finite(value) or value < 0.0 or value > high:\n            trap(\"integer conversion out of range\")\n        return (u64)value\n    if value != value or value < 0.0:\n        return 0\n    if value >= high:\n        return mask_of(bits)\n    return (u64)value\n\n## Saturating arithmetic (`+|`, `-|`, `*|`) on `bits`-wide operands in 64-bit words.\nfunc add_overflows_s(a: i64, b: i64, r: i64) -> bool:\n    return ((a ^ r) & (b ^ r)) < 0\n\nfunc sub_overflows_s(a: i64, b: i64, r: i64) -> bool:\n    return ((a ^ b) & (a ^ r)) < 0\n\nfunc mul_overflows_s(a: i64, b: i64) -> bool:\n    if a == 0 or b == 0:\n        return false\n    if a == -1:\n        return b == signed_min(64)\n    if b == -1:\n        return a == signed_min(64)\n    return (a *% b) // b != a\n\npub func adds_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a +% b\n    if add_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return signed_min(bits) if a < 0 else signed_max(bits)\n    return r\n\npub func adds_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    let r = a +% b\n    if r < a or not fits_unsigned(r, bits):\n        return mask_of(bits)\n    return r\n\npub func subs_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a -% b\n    if sub_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return signed_min(bits) if a < 0 else signed_max(bits)\n    return r\n\npub func subs_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if a < b:\n        return 0\n    return a - b\n\npub func muls_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    if mul_overflows_s(a, b) or not fits_signed(a *% b, bits):\n        return signed_min(bits) if (a < 0) != (b < 0) else signed_max(bits)\n    return a *% b\n\npub func muls_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if b != 0 and a > mask_of(bits) // b:\n        return mask_of(bits)\n    return zero_extend(a *% b, bits)\n\n## Checked-to-optional arithmetic (`+\?`, `-\?`, `*\?`): the result through `out`, whether it fit.\npub func qadd_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a +% b\n    if add_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return false\n    *out = r\n    return true\n\npub func qadd_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    let r = a +% b\n    if r < a or not fits_unsigned(r, bits):\n        return false\n    *out = r\n    return true\n\npub func qsub_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a -% b\n    if sub_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return false\n    *out = r\n    return true\n\npub func qsub_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if a < b:\n        return false\n    *out = a - b\n    return true\n\npub func qmul_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    if mul_overflows_s(a, b) or not fits_signed(a *% b, bits):\n        return false\n    *out = a *% b\n    return true\n\npub func qmul_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if b != 0 and a > mask_of(bits) // b:\n        return false\n    *out = a *% b\n    return true\n", 18344})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"memory", 6}), .text = ((lb_str){"import platform\n\nextern func malloc(size: usize) -> void*\?\nextern func c_free as \"free\"(block: void*)\nextern func posix_memalign(memptr: void*\?*, alignment: usize, size: usize) -> i32\nextern func memcpy(target: void*, source: const void*, count: usize) -> void*\nextern func memmove(target: void*, source: const void*, count: usize) -> void*\nextern func memset(target: void*, value: i32, count: usize) -> void*\n\n## What every allocator offers: blocks of bytes at an alignment, optionally\n## resized in place, and given back (\302\24712.4).\npub interface Allocator:\n    mutating func allocate(size: usize, alignment: usize) -> u8[]\?\n    mutating func resize(block: u8[], size: usize) -> bool\n    mutating func release(block: u8[])\n\n## A bump allocator over a caller's bytes. Only the last block can be resized or\n## released; everything goes away together when the buffer does.\npub struct FixedBuffer: Allocator:\n    var data: u8[]\n    var used: usize\n\n    pub static func over(buffer: u8[]) -> FixedBuffer:\n        return FixedBuffer(data = buffer, used = 0)\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return self.data[..<0]\n        let align = alignment if alignment > 0 else 1\n        # the address is what must be aligned, not the offset: the backing span starts\n        # wherever its owner put it\n        let base = (usize)self.data.data\n        let free_at = base + self.used\n        let aligned = (free_at + (align - 1)) & ~(align - 1)\n        if aligned < free_at:\n            return none\n        let start = aligned - base\n        if start > self.data.length or size > self.data.length - start:\n            note_refusal(\"fixed buffer\", size, align, self.used)\n            return none\n        self.used = start + size\n        return self.data[start..<self.used]\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        if size == block.length:\n            return true\n        if block.length == 0:\n            return false\n        let start = (usize)block.data - (usize)self.data.data\n        if start + block.length != self.used:\n            return false\n        if start + size > self.data.length:\n            return false\n        self.used = start + size\n        return true\n\n    pub mutating func release(block: u8[]):\n        if block.length == 0:\n            return\n        if diagnostic:\n            discard(memset(block.data, 221, block.length))    # a fixed buffer releases all at once\n        let start = (usize)block.data - (usize)self.data.data\n        if start + block.length == self.used:\n            self.used = start\n\n## The C library's heap.\npub struct CAllocator: Allocator:\n    var unused: u8\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return u8[]((u8*)8, 0)\n        var align = alignment if alignment > 8 else 8\n        var p: void*\? = none\n        if posix_memalign(&p, align, size) != 0:\n            note_refusal(\"heap\", size, align, 0)\n            return none\n        let block = p else return none\n        return u8[]((u8*)block, size)\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        return size <= block.length\n\n    pub mutating func release(block: u8[]):\n        if block.length == 0:\n            return\n        if not diagnostic:\n            c_free(block.data)\n            return\n        # the diagnostic profile (\302\24719.4): the block is filled with a pattern and held back, so\n        # a use after release reads the pattern rather than the next allocation\n        discard(memset(block.data, 221, block.length))\n        lock(&records_lock)\n        let slot = quarantine_next % quarantine.length\n        if let old = quarantine[slot]:\n            c_free(old.data)\n        quarantine[slot] = block\n        quarantine_next += 1\n        unlock(&records_lock)\n\n## Bump allocation over a parent allocator, released all at once by `reset` or `destroy`\n## (\302\24712.4, \302\24724.3). One thread at a time.\npub struct Arena: Allocator:\n    var parent: Allocator\n    var block: u8[]\n    var used: usize\n\n    pub static func over(parent: Allocator, capacity: usize) -> Arena!:\n        let block = parent.allocate(capacity, 16) else error(exhausted, \"memory.exhausted\")\n        return Arena(parent = parent, block = block, used = 0)\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return self.block[..<0]\n        let align = alignment if alignment > 0 else 1\n        let base = (usize)self.block.data\n        let start = ((base + self.used + align - 1) // align * align) - base\n        let end = start +\? size else return none\n        if end > self.block.length:\n            note_refusal(\"arena\", size, align, self.used)\n            return none\n        self.used = end\n        return self.block[start..<end]\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        if size == block.length:\n            return true\n        if block.length == 0:\n            return false\n        # the last block may grow or shrink in place\n        let start = (usize)block.data - (usize)self.block.data\n        if start + block.length != self.used or start + size > self.block.length:\n            return false\n        self.used = start + size\n        return true\n\n    pub mutating func release(block: u8[]):\n        if diagnostic and block.length > 0:\n            discard(memset(block.data, 221, block.length))    # an arena releases all at once\n\n    ## What has been handed out since the last reset, and what the arena holds in all.\n    pub func in_use() -> usize:\n        return self.used\n    pub func capacity() -> usize:\n        return self.block.length\n\n    ## Forget every allocation; the storage is reused from its start.\n    pub mutating func reset():\n        self.used = 0\n\n    ## Give the storage back to the parent; the arena is empty afterwards.\n    pub mutating func destroy():\n        self.parent.release(self.block)\n        self.block = self.block[..<0]\n        self.used = 0\n\n## Whole pages from the host, each block its own mapping (\302\24712.4). Safe from several threads.\npub struct PageAllocator: Allocator:\n    var unused: u8\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return u8[]((u8*)8, 0)\n        let page = (usize)getpagesize()\n        if alignment > page:\n            note_refusal(\"page allocator\", size, alignment, 0)\n            return none\n        let rounded = (size + page - 1) // page * page\n        let mapped = mmap(none, rounded, 3, private_anonymous, -1, 0) else return none\n        if (usize)mapped == 18446744073709551615:\n            note_refusal(\"page allocator\", size, alignment, 0)\n            return none\n        return u8[]((u8*)mapped, rounded)\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        return size <= block.length\n\n    pub mutating func release(block: u8[]):\n        if block.length == 0:\n            return\n        if not diagnostic:\n            discard(munmap(block.data, block.length))\n            return\n        # the diagnostic profile (\302\24719.4): the mapping is filled and kept for a while, so a\n        # use after release reads the pattern rather than faulting or reading a new mapping\n        discard(memset(block.data, 221, block.length))\n        lock(&records_lock)\n        let slot = held_next % held_pages.length\n        if let old = held_pages[slot]:\n            discard(munmap(old.data, old.length))\n        held_pages[slot] = block\n        held_next += 1\n        unlock(&records_lock)\n\nextern func mmap(address: void*\?, length: usize, protection: i32, flags: i32, descriptor: i32, offset: i64) -> void*\?\n## `MAP_PRIVATE | MAP_ANON`: `MAP_ANON` is 0x1000 on macOS and 0x20 on Linux; the\n## protection `PROT_READ | PROT_WRITE` is 3 on both.\nlet private_anonymous: i32 = 4098 if platform.macos else 34\nextern func munmap(address: void*, length: usize) -> i32\nextern func getpagesize() -> i32\n\n## The heap refusing a request is rare and worth a line on standard error: what was asked,\n## so an exhaustion in the field says more than its error code. A fixed buffer running out\n## is ordinary and says nothing.\nfunc note_refusal(who: str, size: usize, alignment: usize, used: usize):\n    var text: u8[160]\n    let line = format(text, f\"memory: the {who} refused {size} bytes at alignment {alignment} (used {used})\\n\") catch failure:\n        return\n    discard(write_bytes(2, line.bytes.data, line.length))\n\nextern func write_bytes as \"write\"(descriptor: i32, buffer: const void*, count: usize) -> isize\n\n## `--profile diagnostic`: set by the startup shim before `startup` runs.\npub var diagnostic: bool\n\n## An allocation the diagnostic profile recorded (\302\24719.4): the block, its size, and where.\npub struct Site:\n    pub var address: void*\?\n    pub var size: usize\n    pub var function: str\n    pub var line: u32\n\nvar sites: Site[256]\nvar site_next: usize\n\n## The diagnostic profile's records are shared by every thread: a short spin lock guards\n## each update, on the atomic `@bool` alone, since this module is below `sync`.\nvar records_lock: @bool\n\nfunc lock(flag: (@bool)*):\n    while true:\n        let (exchanged, observed) = flag.cas(false, true)\n        discard(observed)\n        if exchanged:\n            return\n\nfunc unlock(flag: (@bool)*):\n    flag.store(false)\n\n## Called by the compiled program after each allocation under `--profile diagnostic`.\n## The record keeps the most recent 256 allocations, oldest first: once full, the oldest\n## goes and the newest takes the last place.\npub func note_site(address: void*\?, size: usize, function: str, line: u32):\n    lock(&records_lock)\n    if site_next < sites.length:\n        sites[site_next] = Site(address = address, size = size, function = function, line = line)\n    else:\n        var i: usize = 1\n        while i < sites.length:\n            sites[i - 1] = sites[i]\n            i += 1\n        sites[sites.length - 1] = Site(address = address, size = size, function = function, line = line)\n    site_next += 1\n    unlock(&records_lock)\n\n## The allocations recorded so far, the most recent 256 at most, oldest first. A view of\n## the record: read it while no other thread allocates.\npub func allocation_sites() -> const Site[]:\n    let held = site_next if site_next < sites.length else sites.length\n    return sites[..<held]\n## The released blocks the diagnostic profile still holds, oldest freed first.\nvar quarantine: (u8[]\?)[64]\nvar quarantine_next: usize\n## The released mappings the diagnostic profile still holds, oldest first.\nvar held_pages: (u8[]\?)[8]\nvar held_next: usize\n\npub let exhausted: ErrorCode = ErrorCode.package(1)\npub let unset: ErrorCode = ErrorCode.package(2)\n\nvar c_allocator: CAllocator\n## The current allocator of this thread (\302\24712.3) and the process's initial one.\npub local var allocator: Allocator\npub var heap: Allocator\n\n## Run by the startup shim before `main`, and by `thread.spawn` in a new thread.\npub func startup():\n    heap = &c_allocator\n    allocator = heap\n\npub func copy[T](target: T[], source: const T[], count: usize):\n    if count > target.length or count > source.length:\n        trap(\"index out of bounds\")\n    if count > 0:\n        discard(memcpy(target.data, source.data, count * sizeof(T)))\n\npub func move[T](target: T[], source: const T[], count: usize):\n    if count > target.length or count > source.length:\n        trap(\"index out of bounds\")\n    if count > 0:\n        discard(memmove(target.data, source.data, count * sizeof(T)))\n\npub func set(target: u8[], value: u8):\n    if target.length > 0:\n        discard(memset(target.data, (i32)value, target.length))\n\npub func read[T](address: const void*) -> T:\n    var value: T = ---\n    discard(memcpy(&value, address, sizeof(T)))\n    return value\n\npub func write[T](address: void*, value: T):\n    var copy_of = value\n    discard(memcpy(address, &copy_of, sizeof(T)))\n\n## `block` with `size` bytes: in place when the current allocator can, else a\n## new block with the old bytes copied and the old block released.\npub func grow(block: u8[], size: usize) -> u8[]!:\n    if allocator.resize(block, size):\n        return u8[](block.data, size)\n    let fresh = allocator.allocate(size, 8) else error(exhausted, \"memory.exhausted\")\n    let keep = block.length if block.length < size else size\n    if keep > 0:\n        discard(memcpy(fresh.data, block.data, keep))\n    allocator.release(block)\n    return fresh\n", 12437})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"io", 2}), .text = ((lb_str){"import c\nimport core\nimport memory\nextern func fwrite(data: const void*, size: usize, count: usize, stream: void*) -> usize\nextern func fflush(stream: void*\?) -> i32\nextern func fdopen(descriptor: i32, mode: c.str) -> void*\?\n\n## A borrowed byte source. A successful read returns at most the buffer length;\n## zero for a nonempty buffer means EOF. Empty reads return zero without consuming\n## input. Errors are distinct from EOF. The implementing object owns its lifetime.\npub interface Reader:\n    mutating func read(buffer: u8[]) -> usize!\n\n## A borrowed byte sink (\302\24714.4). A write may accept fewer bytes than supplied;\n## callers needing the whole payload use `write_all`. Empty writes return zero.\n## A failure may follow earlier successful writes; the view never owns the sink.\npub interface Writer:\n    mutating func write(data: const u8[]) -> usize!\n\npub let unexpected_eof: ErrorCode = ErrorCode.package(14)\npub let no_progress: ErrorCode = ErrorCode.package(15)\npub let invalid_count: ErrorCode = ErrorCode.package(16)\npub let invalid_buffer: ErrorCode = ErrorCode.package(17)\n\n## Fill `buffer`, or fail at EOF or on a source error. Optional `transferred` is\n## reset to zero on entry and updated after each successful read, including before\n## a later failure. It must not overlap the buffer or the source's state. No call\n## reaches the source for an empty buffer. The source remains borrowed and open.\npub func read_exact(source: Reader, buffer: u8[], transferred: usize*\? = none) -> !:\n    var done: usize = 0\n    if let progress = transferred:\n        *progress = 0\n    while done < buffer.length:\n        let count = try source.read(buffer[done..])\n        if count > buffer.length - done:\n            error(invalid_count, \"the reader returned more bytes than requested\")\n        if count == 0:\n            error(unexpected_eof, \"the reader ended before the buffer was filled\")\n        done += count\n        if let progress = transferred:\n            *progress = done\n\n## Write all bytes, preserving confirmed progress through `transferred` on error.\n## The progress pointer must not overlap the data or sink state. A zero-length\n## successful write on nonempty input fails with `no_progress` instead of spinning.\n## This does not flush or close the borrowed sink. Empty input makes no sink call.\npub func write_all(destination: Writer, data: const u8[], transferred: usize*\? = none) -> !:\n    var done: usize = 0\n    if let progress = transferred:\n        *progress = 0\n    while done < data.length:\n        let count = try destination.write(data[done..])\n        if count > data.length - done:\n            error(invalid_count, \"the writer returned more bytes than supplied\")\n        if count == 0:\n            error(no_progress, \"the writer accepted no bytes\")\n        done += count\n        if let progress = transferred:\n            *progress = done\n\n## Copy at most `limit` bytes through caller-owned scratch storage; stop earlier\n## at EOF. Reads never consume beyond the limit. `transferred` counts confirmed\n## destination bytes, including before a failure; source consumption can be ahead\n## by one scratch buffer if writing fails. Scratch and progress must not overlap\n## either endpoint's state/data or each other. No allocation, flush or close occurs.\npub func copy_limit(source: Reader, destination: Writer, buffer: u8[], limit: usize, transferred: usize*\? = none) -> usize!:\n    var done: usize = 0\n    if let progress = transferred:\n        *progress = 0\n    if limit == 0:\n        return 0\n    if buffer.length == 0:\n        error(invalid_buffer, \"copying requires a nonempty scratch buffer\")\n    while done < limit:\n        let available = limit - done\n        let requested = buffer.length if buffer.length < available else available\n        let count = try source.read(buffer[..<requested])\n        if count > requested:\n            error(invalid_count, \"the reader returned more bytes than requested\")\n        if count == 0:\n            break\n        var written: usize = 0\n        write_all(destination, buffer[..<count], &written) catch failure:\n            if let progress = transferred:\n                *progress = done + written\n            error(failure.code, failure.message)\n        done += written\n        if let progress = transferred:\n            *progress = done\n    return done\n\n## A cursor over borrowed bytes. Copying the reader copies its position, not its\n## data. The backing storage must outlive the reader and every read using it.\npub struct SliceReader: Reader:\n    var data: const u8[]\n    var position: usize\n\n    pub static func over(data: const u8[]) -> SliceReader:\n        return SliceReader(data = data, position = 0)\n\n    pub func remaining() -> usize:\n        return self.data.length - self.position\n\n    ## Copy up to the buffer length; zero means no bytes remain (or an empty read).\n    pub mutating func read(buffer: u8[]) -> usize!:\n        let left = self.remaining()\n        let count = buffer.length if buffer.length < left else left\n        memory.move(buffer, self.data[self.position..], count)\n        self.position += count\n        return count\n\n## A writer into fixed borrowed storage. Copying it copies the cursor and aliases\n## storage. Writes may be short; once full, a nonempty write fails with `full`.\npub struct SliceWriter: Writer:\n    var data: u8[]\n    var used: usize\n\n    pub static func over(data: u8[]) -> SliceWriter:\n        return SliceWriter(data = data, used = 0)\n\n    ## View of confirmed written bytes, borrowed from the caller's storage.\n    pub func written() -> const u8[]:\n        return self.data[..<self.used]\n\n    pub mutating func write(data: const u8[]) -> usize!:\n        if data.length == 0:\n            return 0\n        let left = self.data.length - self.used\n        if left == 0:\n            error(full, \"the destination buffer is full\")\n        let count = data.length if data.length < left else left\n        memory.move(self.data[self.used..], data, count)\n        self.used += count\n        return count\n\n## Buffered input over a borrowed source and nonempty caller-owned storage. Both\n## must outlive this adapter. Storage must not overlap source state or read buffers.\n## Construct with `over`; serialize access and do not use copied adapters together.\n## Reads may prefetch beyond the requested bytes. The adapter never closes its source.\npub struct BufferedReader: Reader:\n    var source: Reader\n    var storage: u8[]\n    var position: usize\n    var used: usize\n\n    pub static func over(source: Reader, storage: u8[]) -> BufferedReader!:\n        if storage.length == 0:\n            error(invalid_buffer, \"buffered input requires nonempty storage\")\n        return BufferedReader(source = source, storage = storage, position = 0, used = 0)\n\n    ## Unread bytes already fetched. No source operation occurs.\n    pub func buffered() -> usize:\n        return self.used - self.position\n\n    ## Return buffered bytes first, otherwise perform one source read. Empty reads\n    ## do not call the source. EOF is not cached, allowing a growing source to resume.\n    pub mutating func read(buffer: u8[]) -> usize!:\n        if buffer.length == 0:\n            return 0\n        if self.position == self.used:\n            let count = try self.source.read(self.storage)\n            if count > self.storage.length:\n                error(invalid_count, \"the reader returned more bytes than requested\")\n            self.position = 0\n            self.used = count\n        let available = self.buffered()\n        let count = buffer.length if buffer.length < available else available\n        memory.copy(buffer, self.storage[self.position..], count)\n        self.position += count\n        return count\n\n## Buffered output over a borrowed sink and nonempty caller-owned storage. Both\n## must outlive this adapter; storage must not overlap sink state or write input.\n## Construct with `over`; serialize access and do not use copied adapters together.\n## Explicitly flush before discarding the adapter. There is no implicit flush/close.\npub struct BufferedWriter: Writer:\n    var destination: Writer\n    var storage: u8[]\n    var used: usize\n\n    pub static func over(destination: Writer, storage: u8[]) -> BufferedWriter!:\n        if storage.length == 0:\n            error(invalid_buffer, \"buffered output requires nonempty storage\")\n        return BufferedWriter(destination = destination, storage = storage, used = 0)\n\n    ## Bytes accepted by this adapter but not yet confirmed by the destination.\n    pub func buffered() -> usize:\n        return self.used\n\n    ## Drain this buffer, preserving the unconfirmed suffix if the sink fails.\n    ## Retrying does not resend bytes confirmed by earlier successful sink writes.\n    ## This neither flushes downstream buffers nor requests filesystem durability.\n    pub mutating func flush() -> !:\n        var written: usize = 0\n        write_all(self.destination, self.storage[..<self.used], &written) catch failure:\n            self.used -= written\n            memory.move(self.storage, self.storage[written..], self.used)\n            error(failure.code, failure.message)\n        self.used = 0\n\n    ## Accept up to the remaining capacity. A full buffer is drained before any\n    ## new input is accepted; a failure accepts none of this call's input. Empty\n    ## writes do not drain the buffer. Use write_all to accept an entire payload.\n    pub mutating func write(data: const u8[]) -> usize!:\n        if data.length == 0:\n            return 0\n        if self.used == self.storage.length:\n            try self.flush()\n        let available = self.storage.length - self.used\n        let count = data.length if data.length < available else available\n        memory.copy(self.storage[self.used..], data, count)\n        self.used += count\n        return count\n\n## A compile-time source position, the value of `luce.location`.\npub struct Location:\n    pub var file: str\n    pub var line: u32\n    pub var function: str\n\npub let closed: ErrorCode = ErrorCode.package(3)\n\n## A C stream. Every write is flushed so that it never reorders against `print`.\npub struct File: Writer:\n    var descriptor: i32\n    var stream: void*\?\n\n    pub mutating func write(data: const u8[]) -> usize!:\n        if self.stream == none:\n            self.stream = fdopen(self.descriptor, \"w\")\n        let stream = self.stream else error(closed, \"the stream could not be opened\")\n        discard(fflush(none))\n        var written: usize = 0\n        if data.length > 0:\n            written = fwrite(data.data, 1, data.length, stream)\n        let flushed = fflush(stream)\n        if written != data.length or flushed != 0:\n            error(closed, \"the stream refused the bytes\")\n        return written\n\nvar out_file: File = File(descriptor = 1, stream = none)\nvar err_file: File = File(descriptor = 2, stream = none)\n\npub func stdout() -> Writer:\n    return &out_file\n\npub func stderr() -> Writer:\n    return &err_file\n\npub let full: ErrorCode = ErrorCode.package(4)\n\n## The sink a formatted string offers a `Display` value (\302\24714.4): it appends to the buffer\n## the compiler is filling, and fails once that buffer is full, as `format` then does.\npub struct FormatSink: Writer:\n    var buffer: core.FormatBuffer*\n\n    pub mutating func write(data: const u8[]) -> usize!:\n        if core.format_put(self.buffer, data.data, data.length) != 0:\n            error(full, \"the buffer is full\")\n        return data.length\n\n## The process's directories (\302\24716.6): `from io import path`, then `path.user()`. Each is\n## a `str` view of environment storage the system owns, or fresh storage from the current\n## allocator where one has to be built.\npub struct path:\n    var unused: u8\n\n    ## The user's home directory: `$HOME`.\n    pub static func user() -> str!:\n        let home = getenv(\"HOME\") else error(io_path_failed, \"no home directory\")\n        return (str)home\n\n    pub static func home() -> str!:\n        return try path.user()\n\n    ## Where temporary files go: `$TMPDIR`, else `/tmp`.\n    pub static func temp() -> str:\n        let dir = getenv(\"TMPDIR\") else return \"/tmp\"\n        return (str)dir\n\n    ## Where configuration lives: `$XDG_CONFIG_HOME`, else `$HOME/.config`.\n    pub static func config() -> str!:\n        if let set = getenv(\"XDG_CONFIG_HOME\"):\n            return (str)set\n        let home = try path.user()\n        let buffer = try alloc u8[home.length + 8]\n        return try format(buffer, f\"{home}/.config\")\n\nextern func getenv(name: c.str) -> c.str\?\npub let io_path_failed: ErrorCode = ErrorCode.package(13)\n", 12534})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"luce", 4}), .text = ((lb_str){"## The derived bounds of \302\24714.4: every type with `==` is Equatable, every hashable\n## one Hashable, every ordered one Comparable. Nothing implements them by hand.\n\nimport io\n\npub interface Equatable:\n    func equals(other: void*) -> bool\npub interface Hashable:\n    func hashed() -> u64\npub interface Comparable:\n    func compare(other: void*) -> i64\n\n## The protocols `for` consumes (\302\2478.3, \302\24714.4): a value iterator answers each element\n## until `none`; an iterable answers a fresh iterator of its own concrete type.\npub interface Iterator[T]:\n    mutating func next() -> T\?\npub interface Iterable[T, I: Iterator[T]]:\n    func iterator() -> I\n\n## A value that writes itself to a sink (\302\24714.4); formatted strings call it for each field.\npub interface Display:\n    func display(sink: io.Writer) -> !\n\n## Compile-time facts about the use site; the backend replaces them (\302\2479.1).\npub let file: str = \"\"\npub let line: u32 = 0\npub let function: str = \"\"\npub let location: io.Location = io.Location(file = \"\", line = 0, function = \"\")\n", 1030})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"atomic", 6}), .text = ((lb_str){"## Memory orderings for the operations of `@T` (\302\24715.1).\npub enum Ordering as u8:\n    relaxed = 1\n    acquire = 2\n    release = 3\n    acq_rel = 4\n    seq_cst = 5\n\n## A standalone fence; the backend supplies the instruction.\npub func fence(order: Ordering):\n    discard(order)\n", 276})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"thread", 6}), .text = ((lb_str){"import c\nimport memory\nimport platform\n\nextern func pthread_create(thread: void*\?*, attributes: void*\?, start: func(void*) -> void*\?, argument: void*) -> i32\nextern func pthread_join(thread: void*, result: void*\?*\?) -> i32\nextern func pthread_detach(thread: void*) -> i32\nextern func pthread_self() -> void*\nextern func pthread_attr_init(attributes: void*) -> i32\nextern func pthread_attr_setstacksize(attributes: void*, size: usize) -> i32\nextern func pthread_attr_destroy(attributes: void*) -> i32\n## macOS names the calling thread; Linux names one by handle. Both cap a name at 15 bytes.\nextern func mac_setname as \"pthread_setname_np\"(name: c.str) -> i32\nextern func linux_setname as \"pthread_setname_np\"(thread: void*, name: c.str) -> i32\nextern func sched_yield() -> i32\nextern func nanosleep(request: const Duration*, remaining: Duration*\?) -> i32\nextern func getpagesize() -> i32\n\nextern struct Duration:\n    seconds: i64\n    nanoseconds: i64\n\npub let failed: ErrorCode = ErrorCode.package(5)\n\n## `PTHREAD_STACK_MIN` on both hosts: a smaller stack is raised to it.\nlet least_stack: usize = 16384\n## The longest name a thread may carry, with its NUL.\nlet name_room: usize = 16\n\n## A running thread; the zero value is no thread at all, so arrays of handles exist.\npub struct Handle:\n    var id: void*\?\n\n    pub func join() -> !:\n        let id = self.id else error(failed, \"no thread to join\")\n        if pthread_join(id, none) != 0:\n            error(failed, \"join\")\n\n    pub func detach():\n        let id = self.id else return\n        discard(pthread_detach(id))\n\n## What a new thread starts with: the entry, its context, its name in a heap block of\n## `name_room` bytes, NUL-terminated, and the allocator rule of \302\24715.3.\nstruct Start:\n    var entry: func(void*\?) -> unit\n    var context: void*\?\n    var name: u8[]\n    var name_length: usize\n\nfunc trampoline(raw: void*) -> void*\?:\n    let start = (Start*)raw\n    memory.allocator = memory.heap\n    let entry = start.entry\n    let context = start.context\n    if start.name_length > 0:\n        let text = (c.str)(str)start.name[..<start.name_length]\n        if platform.macos:\n            discard(mac_setname(text))\n        else:\n            discard(linux_setname(pthread_self(), text))\n    free(start.name) in memory.heap\n    free(start) in memory.heap\n    entry(context)\n    return none\n\n## Start a thread running `entry(context)`. `stack` is its stack in bytes, the host's\n## default when 0, else at least `PTHREAD_STACK_MIN` and whole pages; `name` is what the\n## host's tools show for it, its first fifteen bytes.\npub func spawn(entry: func(void*\?) -> unit, context: void*\?, stack: usize = 0, name: str = \"\") -> Handle!:\n    let copy = try alloc u8[name_room] in memory.heap\n    let kept = name.length if name.length < name_room - 1 else name_room - 1\n    memory.copy(copy, name.bytes, kept)\n    copy[kept] = 0\n    let start = new Start(entry = entry, context = context, name = copy, name_length = kept) in memory.heap catch failure:\n        free(copy) in memory.heap\n        error(memory.exhausted, \"memory.exhausted\")\n    var attributes: u64[16]\n    if pthread_attr_init((void*)&attributes[0]) != 0:\n        free(copy) in memory.heap\n        free(start) in memory.heap\n        error(failed, \"spawn\")\n    if stack > 0:\n        let page = (usize)getpagesize()\n        var size = stack if stack > least_stack else least_stack\n        size = (size + page - 1) // page * page\n        if pthread_attr_setstacksize((void*)&attributes[0], size) != 0:\n            discard(pthread_attr_destroy((void*)&attributes[0]))\n            free(copy) in memory.heap\n            free(start) in memory.heap\n            error(failed, \"the stack size is refused\")\n    var id: void*\? = none\n    let created = pthread_create(&id, (void*)&attributes[0], trampoline, (void*)start)\n    discard(pthread_attr_destroy((void*)&attributes[0]))\n    if created != 0:\n        free(copy) in memory.heap\n        free(start) in memory.heap\n        error(failed, \"spawn\")\n    let thread = id else error(failed, \"spawn\")\n    return Handle(id = thread)\n\npub func current() -> Handle:\n    return Handle(id = pthread_self())\n\n## A hint to the processor inside a spin loop.\npub func pause():\n    asm arm64:\n        yield\n    asm x86_64:\n        pause\n\npub func yield():\n    discard(sched_yield())\n\n## Sleep for at least `milliseconds`: a signal that interrupts the sleep leaves the time\n## remaining, which is slept again.\npub func sleep(milliseconds: u64):\n    var request = Duration(seconds = (i64)(milliseconds // 1000), nanoseconds = (i64)(milliseconds % 1000) * 1000000)\n    var remaining = Duration(seconds = 0, nanoseconds = 0)\n    while nanosleep(&request, &remaining) != 0 and c.errno() == c.interrupted:\n        request = remaining\n", 4760})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"sync", 4}), .text = ((lb_str){"import platform\n\n## macOS: the `ulock` calls libSystem builds its own locks on.\nextern func __ulock_wait(operation: u32, address: void*, value: u64, timeout: u32) -> i32\nextern func __ulock_wake(operation: u32, address: void*, wake_value: u64) -> i32\n## Linux: the futex system call, through `syscall`; the number is the architecture's.\nextern func syscall(number: i64, ...) -> i64\n\nlet compare_and_wait: u32 = 1\nlet wake_all: u32 = 256\nlet futex_number: i64 = 98 if platform.arm64 else 202\nlet futex_wait_private: i32 = 128\nlet futex_wake_private: i32 = 129\n\n## Sleep in the kernel while the word at `address` still holds `value`; a change\n## or a wake returns, and so may nothing at all, so every caller loops.\nfunc sleep_on(address: void*, value: u32):\n    if platform.macos:\n        discard(__ulock_wait(compare_and_wait, address, (u64)value, 0))\n    else:\n        let no_timeout: void*\? = none\n        discard(syscall(futex_number, address, futex_wait_private, value, no_timeout))\n\nfunc wake_one(address: void*):\n    if platform.macos:\n        discard(__ulock_wake(compare_and_wait, address, 0))\n    else:\n        discard(syscall(futex_number, address, futex_wake_private, 1))\n\nfunc wake_every(address: void*):\n    if platform.macos:\n        discard(__ulock_wake(compare_and_wait | wake_all, address, 0))\n    else:\n        discard(syscall(futex_number, address, futex_wake_private, 2147483647))\n\n## A lock whose waiters sleep: zero is unlocked, so `var lock: Mutex` is ready to\n## use; one is locked; two is locked with someone asleep on it.\npub struct Mutex:\n    var state: @u32\n\n    pub mutating func lock():\n        let (taken, seen) = self.state.cas(0, 1, .acquire, .relaxed)\n        if taken:\n            return\n        var current = seen\n        if current != 2:\n            current = self.state.swap(2, .acquire)\n        while current != 0:\n            sleep_on((void*)&self.state, 2)\n            current = self.state.swap(2, .acquire)\n\n    pub mutating func unlock():\n        if self.state.swap(0, .release) == 2:\n            wake_one((void*)&self.state)\n\n    pub mutating func try_lock() -> bool:\n        let (taken, seen) = self.state.cas(0, 1, .acquire, .relaxed)\n        discard(seen)\n        return taken\n\n## A sequence number waiters watch; every signal advances it and wakes.\npub struct Condition:\n    var sequence: @u32\n\n    pub mutating func wait(mutex: Mutex*):\n        let seen = self.sequence.load(.acquire)\n        mutex.unlock()\n        sleep_on((void*)&self.sequence, seen)\n        mutex.lock()\n\n    pub mutating func signal():\n        discard(self.sequence.add(1, .release))\n        wake_one((void*)&self.sequence)\n\n    pub mutating func broadcast():\n        discard(self.sequence.add(1, .release))\n        wake_every((void*)&self.sequence)\n\n## Runs its function exactly once; later callers wait for the first to finish.\npub struct Once:\n    var state: @u32\n\n    pub mutating func run(function: func() -> unit):\n        let (first, seen) = self.state.cas(0, 1, .acq_rel, .acquire)\n        discard(seen)\n        if first:\n            function()\n            self.state.store(2, .release)\n            wake_every((void*)&self.state)\n            return\n        while self.state.load(.acquire) != 2:\n            sleep_on((void*)&self.state, 1)\n\n## A counting semaphore whose waiters sleep.\npub struct Semaphore:\n    var count: @u32\n\n    pub mutating func acquire():\n        while true:\n            let n = self.count.load(.acquire)\n            if n > 0:\n                let (taken, seen) = self.count.cas(n, n - 1, .acq_rel, .relaxed)\n                discard(seen)\n                if taken:\n                    return\n            else:\n                sleep_on((void*)&self.count, 0)\n\n    pub mutating func release():\n        discard(self.count.add(1, .release))\n        wake_one((void*)&self.count)\n", 3823})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"files", 5}), .text = ((lb_str){"import c\nimport memory\nimport platform\nimport io\n\nextern func open(path: c.str, flags: i32, ...) -> i32\nextern func close(descriptor: i32) -> i32\nextern func c_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func c_write as \"write\"(descriptor: i32, buffer: const void*, count: usize) -> isize\nextern func lseek(descriptor: i32, offset: i64, whence: i32) -> i64\nextern func fsync(descriptor: i32) -> i32\nextern func opendir(path: c.str) -> void*\?\nextern func readdir_macos as \"readdir\"(directory: void*) -> MacEntry*\?\nextern func readdir_linux as \"readdir\"(directory: void*) -> LinuxEntry*\?\nextern func closedir(directory: void*) -> i32\nextern func access(path: c.str, mode: i32) -> i32\n\n## A directory entry as macOS lays it out (`struct dirent`, 64-bit inodes).\nextern struct MacEntry:\n    inode: u64\n    seek: u64\n    length: u16\n    name_length: u16\n    kind: u8\n    name: u8[1024]\n\n## A directory entry as Linux lays it out: the name is NUL-terminated, not counted.\nextern struct LinuxEntry:\n    inode: u64\n    offset: i64\n    length: u16\n    kind: u8\n    name: u8[256]\n\n## The next entry's name, or none at the end; `.` and `..` are entries like any other.\nfunc next_entry(directory: void*) -> str\?!:\n    while true:\n        c.set_errno(0)\n        if platform.macos:\n            if let entry = readdir_macos(directory):\n                return (str)entry.name[..<(usize)entry.name_length]\n        else:\n            if let entry = readdir_linux(directory):\n                var n: usize = 0\n                while n < entry.name.length and entry.name[n] != 0:\n                    n += 1\n                return (str)entry.name[..<n]\n        let number = c.errno()\n        if number == c.interrupted:\n            continue\n        if number != 0:\n            error(classify_error(number), \"the directory could not be read\")\n        return none\n\n## `open` flags: macOS keeps the BSD values, Linux its own (\302\24719.5).\nlet write_only: i32 = 1\nlet create: i32 = 512 if platform.macos else 64\nlet truncate: i32 = 1024 if platform.macos else 512\nlet close_on_exec: i32 = 16777216 if platform.macos else 524288\nlet append_flag: i32 = 8 if platform.macos else 1024\nlet exclusive_flag: i32 = 2048 if platform.macos else 128\nlet would_block_errno: i32 = 35 if platform.macos else 11\nlet transfer_limit: usize = 1073741824\n\npub let missing: ErrorCode = ErrorCode.package(6)\npub let permission_denied: ErrorCode = ErrorCode.package(18)\npub let already_exists: ErrorCode = ErrorCode.package(19)\npub let no_space: ErrorCode = ErrorCode.package(20)\npub let would_block: ErrorCode = ErrorCode.package(21)\npub let invalid_options: ErrorCode = ErrorCode.package(22)\npub let too_large: ErrorCode = ErrorCode.package(23)\npub let not_directory: ErrorCode = ErrorCode.package(25)\npub let is_directory: ErrorCode = ErrorCode.package(26)\npub let read_only_filesystem: ErrorCode = ErrorCode.package(27)\n\n## File opening policy. `replace` creates or truncates; `create_new` refuses an\n## existing path; `append` creates if needed and makes each write append atomically.\n## Creation permissions are filtered by the process umask, never changed afterward.\npub enum OpenMode as u8:\n    read = 0\n    read_write = 1\n    replace = 2\n    create_new = 3\n    append = 4\n\npub enum SeekOrigin as u8:\n    start = 0\n    current = 1\n    end = 2\n\n## One owned descriptor. The zero value is closed. Borrow through a pointer or an\n## io interface; copying this value does not duplicate ownership or the OS handle.\n## A copied value must not be independently closed. Calls on one handle require\n## external synchronization. `close` reports errors; `destroy` is unwind cleanup.\npub struct File: io.Reader, io.Writer:\n    var handle: i32\?\n\n    ## Open a close-on-exec descriptor. Only the named creation modes create paths.\n    pub static func open(path: c.str, mode: OpenMode = OpenMode.read, permissions: u32 = 420) -> File!:\n        if permissions > 4095:\n            error(invalid_options, \"file permissions must fit the Unix mode bits\")\n        var flags = close_on_exec\n        if mode == OpenMode.read_write:\n            flags |= 2\n        elif mode == OpenMode.replace:\n            flags |= write_only | create | truncate\n        elif mode == OpenMode.create_new:\n            flags |= write_only | create | exclusive_flag\n        elif mode == OpenMode.append:\n            flags |= write_only | create | append_flag\n        elif mode != OpenMode.read:\n            error(invalid_options, \"unknown file opening mode\")\n        var fd = open(path, flags, permissions)\n        while fd < 0 and c.errno() == c.interrupted:\n            fd = open(path, flags, permissions)\n        if fd < 0:\n            error(classify_error(c.errno()), \"the file could not be opened\")\n        return File(handle = fd)\n\n    ## Borrow the descriptor for OS interoperability; none after close. The caller\n    ## must not close it or retain it past this owner's lifetime.\n    pub func descriptor() -> i32\?:\n        return self.handle\n\n    ## Read some bytes, retrying interruption. Zero for nonempty storage is EOF;\n    ## empty input makes no system call. The handle must be open even for empty I/O.\n    pub mutating func read(buffer: u8[]) -> usize!:\n        let fd = self.handle else error(io.closed, \"the file is closed\")\n        if buffer.length == 0:\n            return 0\n        let count = buffer.length if buffer.length < transfer_limit else transfer_limit\n        var received = c_read(fd, buffer.data, count)\n        while received < 0 and c.errno() == c.interrupted:\n            received = c_read(fd, buffer.data, count)\n        if received < 0:\n            error(classify_error(c.errno()), \"the file could not be read\")\n        return (usize)received\n\n    ## Write some bytes, retrying interruption. Use io.write_all for a full payload.\n    ## Success confirms an OS write, not durable storage; call sync when required.\n    pub mutating func write(data: const u8[]) -> usize!:\n        let fd = self.handle else error(io.closed, \"the file is closed\")\n        if data.length == 0:\n            return 0\n        let count = data.length if data.length < transfer_limit else transfer_limit\n        var written = c_write(fd, data.data, count)\n        while written < 0 and c.errno() == c.interrupted:\n            written = c_write(fd, data.data, count)\n        if written < 0:\n            error(classify_error(c.errno()), \"the file could not be written\")\n        return (usize)written\n\n    ## Seek a seekable file and return its resulting byte offset. Pipes and other\n    ## unseekable descriptors report failure instead of pretending their size is zero.\n    pub mutating func seek(offset: i64, origin: SeekOrigin = SeekOrigin.start) -> i64!:\n        let fd = self.handle else error(io.closed, \"the file is closed\")\n        var position = lseek(fd, offset, (i32)origin)\n        while position < 0 and c.errno() == c.interrupted:\n            position = lseek(fd, offset, (i32)origin)\n        if position < 0:\n            error(classify_error(c.errno()), \"the file could not be positioned\")\n        return position\n\n    ## Request the OS's fsync durability boundary for this file; this does not sync\n    ## a containing directory or promise persistence beyond the OS/device contract.\n    pub mutating func sync() -> !:\n        let fd = self.handle else error(io.closed, \"the file is closed\")\n        var result = fsync(fd)\n        while result < 0 and c.errno() == c.interrupted:\n            result = fsync(fd)\n        if result < 0:\n            error(classify_error(c.errno()), \"the file could not be synchronized\")\n\n    ## Consume ownership before closing, so repeated calls on this value are safe\n    ## even after failure. Never retry close: a reused descriptor may belong to\n    ## another thread. A reported failure must not be retried using descriptor().\n    pub mutating func close() -> !:\n        let fd = self.handle else return\n        self.handle = none\n        if close(fd) != 0:\n            error(classify_error(c.errno()), \"the file could not be closed\")\n\n    ## Best-effort cleanup while unwinding another error. Use close explicitly on\n    ## the successful path when delayed close errors must be reported to the caller.\n    pub mutating func destroy():\n        self.close() catch failure:\n            discard(failure)\n\nfunc classify_error(number: i32) -> ErrorCode:\n    if number == 2:\n        return missing\n    if number == 1 or number == 13:\n        return permission_denied\n    if number == 17:\n        return already_exists\n    if number == 28:\n        return no_space\n    if number == 20:\n        return not_directory\n    if number == 21:\n        return is_directory\n    if number == 30:\n        return read_only_filesystem\n    if number == would_block_errno:\n        return would_block\n    return failed\n\n## Whether the path currently resolves to an existing object, following symlinks.\n## This convenience form returns false on lookup errors; use exists_checked when\n## permission or I/O failures must be distinguished from absence. It never opens a\n## file, so checking a FIFO cannot block waiting for a writer.\npub func exists(path: c.str) -> bool:\n    return exists_checked(path) catch failure:\n        discard(failure)\n        recover false\n\n## Checked existence lookup. Missing components, non-directory parent components\n## and dangling symlinks return false. Other failures retain their error category.\npub func exists_checked(path: c.str) -> bool!:\n    var result = access(path, 0)\n    while result < 0 and c.errno() == c.interrupted:\n        result = access(path, 0)\n    if result == 0:\n        return true\n    let number = c.errno()\n    if number == 2 or number == 20:\n        return false\n    error(classify_error(number), \"the path could not be inspected\")\npub let failed: ErrorCode = ErrorCode.package(7)\n\n## Read through EOF, including files whose size changes or cannot be sought. The\n## result is an allocation of the current allocator; free the returned span there.\n## Use read_limit for untrusted or potentially unbounded input.\npub func read(path: c.str) -> u8[]!:\n    return try read_limit(path, 18446744073709551615)\n\n## Read a whole file up to `limit` bytes. One extra byte may be read to distinguish\n## an exact fit from excess input; excess fails with too_large, never truncates.\n## All allocations and the descriptor are released on failure. An empty result is\n## still an owned zero-length allocation, following read's existing free contract.\npub func read_limit(path: c.str, limit: usize) -> u8[]!:\n    var file = try File.open(path)\n    defer file.destroy()\n    var bytes: u8[]\n    errdefer release_buffer(bytes)\n    var used: usize = 0\n    var scratch: u8[4096]\n    while true:\n        let remaining = limit - used\n        let requested = 1 if remaining == 0 else (remaining if remaining < scratch.length else scratch.length)\n        let count = try file.read(scratch[..<requested])\n        if count == 0:\n            break\n        if remaining == 0:\n            error(too_large, \"the file exceeds the read limit\")\n        let needed = used + count\n        if needed > bytes.length:\n            var capacity = bytes.length *\? 2 else limit\n            if capacity < 4096:\n                capacity = 4096\n            if capacity < needed:\n                capacity = needed\n            if capacity > limit:\n                capacity = limit\n            if bytes.length == 0:\n                bytes = try alloc u8[capacity]\n            else:\n                bytes = try memory.grow(bytes, capacity)\n        memory.copy(bytes[used..], scratch, count)\n        used += count\n    try file.close()\n    if used == bytes.length and used > 0:\n        return bytes\n    let exact = try alloc u8[used]\n    memory.copy(exact, bytes, used)\n    release_buffer(bytes)\n    return exact\n\n## Create or truncate and write all bytes, reporting write and close failures.\n## This is neither atomic replacement nor durable sync; use those operations\n## explicitly when their guarantees are required.\npub func write(path: c.str, data: const u8[]) -> !:\n    var file = try File.open(path, OpenMode.replace)\n    defer file.destroy()\n    try io.write_all(&file, data)\n    try file.close()\n\nfunc release_buffer(bytes: u8[]):\n    if bytes.length > 0:\n        free(bytes)\n\n## One owned directory stream; the zero value is closed. Copying does not duplicate\n## ownership. Borrow it for iteration and serialize access to the stream.\npub struct Directory:\n    var handle: void*\?\n\n    pub static func open(path: c.str) -> Directory!:\n        var stream = opendir(path)\n        while stream == none and c.errno() == c.interrupted:\n            stream = opendir(path)\n        let directory = stream else error(classify_error(c.errno()), \"the directory could not be opened\")\n        return Directory(handle = directory)\n\n    ## The next name excluding dot and dot-dot, or none at end. Names are raw path\n    ## bytes, not guaranteed UTF-8. The view expires on the next call or close.\n    pub mutating func next() -> str\?!:\n        let directory = self.handle else error(io.closed, \"the directory is closed\")\n        while true:\n            let name = try next_entry(directory) else return none\n            if name != \".\" and name != \"..\":\n                return name\n\n    ## Consume ownership even on failure; repeated calls on this value are safe.\n    pub mutating func close() -> !:\n        let directory = self.handle else return\n        self.handle = none\n        if closedir(directory) != 0:\n            error(classify_error(c.errno()), \"the directory could not be closed\")\n\n    ## Best-effort unwind cleanup; use close to observe an error on the success path.\n    pub mutating func destroy():\n        self.close() catch failure:\n            discard(failure)\n\n## The names in a directory, sorted by bytes, without `.` and `..`: each name and the\n## array holding them, exactly as long as the names, are allocations of the current\n## allocator, which `release_list` returns together. On a failure nothing allocated is\n## kept and the directory is closed.\npub func list(path: c.str) -> str[]!:\n    var directory = try Directory.open(path)\n    defer directory.destroy()\n    var names = try alloc str[16]\n    var count: usize = 0\n    errdefer release_entries(names, count)\n    while let name = try directory.next():\n        if count == names.length:\n            let capacity = names.length *\? 2 else error(memory.exhausted, \"the directory listing is too large\")\n            let grown = try alloc str[capacity]\n            memory.copy(grown, names, count)\n            free(names)\n            names = grown\n        let copy = try alloc u8[name.length + 1]\n        memory.copy(copy, name.bytes, name.length)\n        copy[name.length] = 0\n        names[count] = (str)copy[..<name.length]\n        count += 1\n    try directory.close()\n    sort_names(names[..<count])\n    # the array as long as the names, so that `release_list` returns what was allocated\n    if count == 0:\n        free(names)\n        var empty: str[]\n        return empty\n    let exact = try alloc str[count]\n    memory.copy(exact, names, count)\n    free(names)\n    return exact\n\n## In-place heapsort gives large directories O(n log n) comparisons without a\n## second allocation or a recursion depth dependent on filesystem enumeration order.\nfunc sort_names(names: str[]):\n    var root = names.length // 2\n    while root > 0:\n        root -= 1\n        sift_names(names, root, names.length)\n    var end = names.length\n    while end > 1:\n        end -= 1\n        let largest = names[0]\n        names[0] = names[end]\n        names[end] = largest\n        sift_names(names, 0, end)\n\nfunc sift_names(names: str[], start: usize, end: usize):\n    var parent = start\n    while parent < end // 2:\n        var child = parent * 2 + 1\n        if child + 1 < end and names[child] < names[child + 1]:\n            child += 1\n        if not (names[parent] < names[child]):\n            return\n        let saved = names[parent]\n        names[parent] = names[child]\n        names[child] = saved\n        parent = child\n\n## Return what `list` allocated: every name, then the array, to the allocator that is\n## current, which must be the one `list` allocated from. The names are one byte longer\n## than they read, the NUL after each (\302\2475.5).\npub func release_list(names: str[]):\n    release_entries(names, names.length)\n\n## Partial lists still own the whole array allocation, including its unfilled capacity.\nfunc release_entries(names: str[], count: usize):\n    for name in names[..<count]:\n        free(u8[]((u8*)name.bytes.data, name.length + 1))\n    if names.length > 0:\n        free(names)\n", 16609})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"process", 7}), .text = ((lb_str){"import c\nimport memory\nimport platform\n\nextern func pipe(descriptors: i32*) -> i32\nextern func fork() -> i32\nextern func dup2(from_fd: i32, to_fd: i32) -> i32\nextern func close(descriptor: i32) -> i32\nextern func execvp(program: c.str, arguments: void*\?*) -> i32\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func _exit(code: i32) -> never\nextern func waitpid(pid: i32, status: i32*, options: i32) -> i32\nextern func kill(pid: i32, signal: i32) -> i32\nextern func c_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func poll(descriptors: Poll*, count: u32, timeout: i32) -> i32\nextern func fcntl(descriptor: i32, command: i32, ...) -> i32\n\nextern struct Poll:\n    descriptor: i32\n    events: i16\n    returned: i16\n\nlet poll_in: i16 = 1\nlet poll_hang_up: i16 = 16\nlet poll_error: i16 = 8\nlet set_flags: i32 = 4\n## `O_NONBLOCK`: 4 on macOS, 2048 on Linux.\nlet non_blocking: i32 = 4 if platform.macos else 2048\nlet would_block: i32 = 35 if platform.macos else 11\n\npub let failed: ErrorCode = ErrorCode.package(8)\n\n## A captured stream: bytes in the current allocator, grown as the program writes.\nstruct Capture:\n    var descriptor: i32\n    var data: u8[]\n    var used: usize\n    var open: bool\n\n    mutating func pull() -> !:\n        if self.data.length - self.used < 256:\n            if self.data.length == 0:\n                self.data = try alloc u8[1024]\n            else:\n                self.data = try memory.grow(self.data, self.data.length * 2)\n        let n = c_read(self.descriptor, self.data[self.used..].data, self.data.length - self.used)\n        if n == 0:\n            self.open = false\n        elif n > 0:\n            self.used += (usize)n\n        elif c.errno() != c.interrupted and c.errno() != would_block:\n            error(failed, \"the program's output cannot be read\")\n\n    ## What was captured, in an allocation exactly its length, or empty with none; the\n    ## capture's own storage is given back.\n    mutating func take() -> str!:\n        var empty: u8[]\n        if self.used == 0:\n            if self.data.length > 0:\n                free(self.data)\n                self.data = empty\n            return (str)empty\n        let exact = try alloc u8[self.used]\n        memory.copy(exact, self.data, self.used)\n        free(self.data)\n        self.data = empty\n        return (str)exact\n\n    mutating func drop():\n        if self.data.length > 0:\n            free(self.data)\n            var empty: u8[]\n            self.data = empty\n\n## Run `program` with `arguments`, wait for it, and answer its exit status and what it\n## wrote to its standard output and error. The two texts are allocations of the current\n## allocator, each exactly its length, empty ones no allocation at all; `release` gives\n## one back. A capture failure terminates and reaps the child, then closes the pipes and\n## releases the captures; waiting never depends on output we stopped reading. The child\n## does nothing between `fork` and `exec` but move descriptors,\n## so a parent with other threads is safe (\302\24715.3).\npub func run(program: c.str, arguments: const c.str[]) -> (i32, str, str)!:\n    let argv = try alloc void*\?[arguments.length + 2]\n    argv[0] = (void*)program\n    var i: usize = 0\n    while i < arguments.length:\n        argv[i + 1] = (void*)arguments[i]\n        i += 1\n    argv[arguments.length + 1] = none\n    var out_pipe: i32[2]\n    var err_pipe: i32[2]\n    if pipe((i32*)&out_pipe) != 0:\n        free(argv)\n        error(failed, \"run\")\n    if pipe((i32*)&err_pipe) != 0:\n        discard(close(out_pipe[0]))\n        discard(close(out_pipe[1]))\n        free(argv)\n        error(failed, \"run\")\n    let pid = fork()\n    if pid < 0:\n        discard(close(out_pipe[0]))\n        discard(close(out_pipe[1]))\n        discard(close(err_pipe[0]))\n        discard(close(err_pipe[1]))\n        free(argv)\n        error(failed, \"run\")\n    if pid == 0:\n        discard(close(out_pipe[0]))\n        discard(close(err_pipe[0]))\n        if dup2(out_pipe[1], 1) < 0 or dup2(err_pipe[1], 2) < 0:\n            _exit(127)\n        discard(close(out_pipe[1]))\n        discard(close(err_pipe[1]))\n        discard(execvp(program, argv.data))\n        _exit(127)\n    free(argv)\n    discard(close(out_pipe[1]))\n    discard(close(err_pipe[1]))\n    var empty: u8[]\n    var out = Capture(descriptor = out_pipe[0], data = empty, used = 0, open = true)\n    var err = Capture(descriptor = err_pipe[0], data = empty, used = 0, open = true)\n    defer discard(close(out_pipe[0]))\n    defer discard(close(err_pipe[0]))\n    defer out.drop()\n    defer err.drop()\n    try capture(pid, &out, &err)\n    let status = try wait_for(pid)\n    if (status & 127) != 0:\n        error(failed, \"the program was stopped by a signal\")\n    let out_text = try out.take()\n    let err_text = err.take() catch failure:\n        release(out_text)\n        error(failure.code, failure.message)\n    return ((status >> 8) & 255, out_text, err_text)\n\n## Only capture owns the cancellation path. Once it returns, result allocation can fail\n## after wait_for has reaped the child; that must never signal a potentially reused pid.\nfunc capture(pid: i32, out: Capture*, err: Capture*) -> !:\n    errdefer terminate(pid)\n    if fcntl(out.descriptor, set_flags, non_blocking) < 0 or fcntl(err.descriptor, set_flags, non_blocking) < 0:\n        error(failed, \"the program's output cannot be read\")\n    while out.open or err.open:\n        var watched: Poll[2] = ---\n        watched[0] = Poll(descriptor = out.descriptor if out.open else -1, events = poll_in, returned = 0)\n        watched[1] = Poll(descriptor = err.descriptor if err.open else -1, events = poll_in, returned = 0)\n        if poll((Poll*)&watched, 2, -1) < 0:\n            if c.errno() == c.interrupted:\n                continue\n            error(failed, \"the program's output cannot be read\")\n        if out.open and (watched[0].returned & (poll_in | poll_hang_up | poll_error)) != 0:\n            try out.pull()\n        if err.open and (watched[1].returned & (poll_in | poll_hang_up | poll_error)) != 0:\n            try err.pull()\n\n## The child's wait status, waited for again when a signal interrupts the wait.\nfunc wait_for(pid: i32) -> i32!:\n    var status: i32 = 0\n    while waitpid(pid, &status, 0) < 0:\n        if c.errno() != c.interrupted:\n            error(failed, \"run\")\n    return status\n\n## A child may ignore a broken pipe or SIGTERM. SIGKILL stops its writes before waiting.\nfunc terminate(pid: i32):\n    discard(kill(pid, 9))\n    var status: i32 = 0\n    while waitpid(pid, &status, 0) < 0 and c.errno() == c.interrupted:\n        continue\n\n## Give back a text `run` answered, to the allocator that was current then.\npub func release(text: str):\n    if text.length > 0:\n        free(u8[]((u8*)text.bytes.data, text.length))\n\npub func exit(code: i32) -> never:\n    c_exit(code)\n", 6826})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"strings", 7}), .text = ((lb_str){"## Text operations over `str` views; what allocates says so and uses the current allocator,\n## and says how the allocation is given back: `release` for a text made here, `free` for\n## the array `split` answers.\n\nimport c\nimport io\nimport memory\n\npub func starts_with(text: str, prefix: str) -> bool:\n    if prefix.length > text.length:\n        return false\n    return (str)text.bytes[..<prefix.length] == prefix\n\npub func ends_with(text: str, suffix: str) -> bool:\n    if suffix.length > text.length:\n        return false\n    return (str)text.bytes[text.length - suffix.length..] == suffix\n\n## The byte offset of the first `needle` in `text`.\npub func find(text: str, needle: str) -> usize\?:\n    if needle.length > text.length:\n        return none\n    var i: usize = 0\n    while i + needle.length <= text.length:\n        if (str)text.bytes[i..<i + needle.length] == needle:\n            return i\n        i += 1\n    return none\n\n## The byte offset of the last `byte` in `text`.\npub func last(text: str, byte: u8) -> usize\?:\n    var i = text.length\n    while i > 0:\n        i -= 1\n        if text.bytes[i] == byte:\n            return i\n    return none\n\npub func contains(text: str, needle: str) -> bool:\n    return find(text, needle) != none\n\nfunc is_space(byte: u8) -> bool:\n    return byte == ' ' or byte == '\\n' or byte == '\\t' or byte == '\\r'\n\n## `text` without leading and trailing spaces, tabs, and line ends: a view.\npub func trim(text: str) -> str:\n    var start: usize = 0\n    var end = text.length\n    let b = text.bytes\n    while start < end and is_space(b[start]):\n        start += 1\n    while end > start and is_space(b[end - 1]):\n        end -= 1\n    return (str)b[start..<end]\n\n## `text` split at every `separator`, as views into it; the array is an allocation of the\n## current allocator, given back with `free`.\npub func split(text: str, separator: u8) -> str[]!:\n    var count: usize = 1\n    for b in text.bytes:\n        if b == separator:\n            count += 1\n    let parts = try alloc str[count]\n    var n: usize = 0\n    var start: usize = 0\n    var i: usize = 0\n    let b = text.bytes\n    while i < b.length:\n        if b[i] == separator:\n            parts[n] = (str)b[start..<i]\n            n += 1\n            start = i + 1\n        i += 1\n    parts[n] = (str)b[start..]\n    return parts\n\n## The pieces joined with `separator` between them, NUL-terminated in the current\n## allocator; `release` gives it back.\npub func join(pieces: const str[], separator: str) -> str!:\n    var total: usize = 0\n    var i: usize = 0\n    while i < pieces.length:\n        total = total +\? pieces[i].length else error(memory.exhausted, \"the joined text is too large\")\n        if i + 1 < pieces.length:\n            total = total +\? separator.length else error(memory.exhausted, \"the joined text is too large\")\n        i += 1\n    let out = try terminated_buffer(total)\n    var n: usize = 0\n    i = 0\n    while i < pieces.length:\n        memory.copy(out[n..], pieces[i].bytes, pieces[i].length)\n        n += pieces[i].length\n        if i + 1 < pieces.length:\n            memory.copy(out[n..], separator.bytes, separator.length)\n            n += separator.length\n        i += 1\n    out[n] = 0\n    return (str)out[..<n]\n\n## A copy of `text` in the current allocator, NUL-terminated so it may be a `c.str`;\n## `release` gives it back.\npub func copy(text: str) -> str!:\n    let out = try terminated_buffer(text.length)\n    memory.copy(out, text.bytes, text.length)\n    out[text.length] = 0\n    return (str)out[..<text.length]\n\n## A decimal integer, with an optional sign; none when the text is not one.\npub func to_i64(text: str) -> i64\?:\n    let b = text.bytes\n    if b.length == 0:\n        return none\n    var i: usize = 0\n    var negative = false\n    if b[0] == '-' or b[0] == '+':\n        negative = b[0] == '-'\n        i = 1\n    if i >= b.length:\n        return none\n    # the value accumulates on the side of its sign, so the negative endpoint fits\n    var value: i64 = 0\n    while i < b.length:\n        let byte = b[i]\n        if byte < '0' or byte > '9':\n            return none\n        let digit = (i64)(byte - '0')\n        let scaled = value *\? 10 else return none\n        value = (scaled -\? digit if negative else scaled +\? digit) else return none\n        i += 1\n    return value\n\n## ASCII case folding; other bytes pass through. NUL-terminated in the current\n## allocator; `release` gives the text back.\npub func to_upper(text: str) -> str!:\n    let out = try terminated_buffer(text.length)\n    var i: usize = 0\n    for b in text.bytes:\n        out[i] = b - 32 if b >= 'a' and b <= 'z' else b\n        i += 1\n    out[i] = 0\n    return (str)out[..<i]\n\npub func to_lower(text: str) -> str!:\n    let out = try terminated_buffer(text.length)\n    var i: usize = 0\n    for b in text.bytes:\n        out[i] = b + 32 if b >= 'A' and b <= 'Z' else b\n        i += 1\n    out[i] = 0\n    return (str)out[..<i]\n\n## Give back a text `join`, `copy`, `to_upper`, or `to_lower` answered: the allocation is\n## one byte longer than the text, its NUL.\npub func release(text: str):\n    free(u8[]((u8*)text.bytes.data, text.length + 1))\n\n## Allocate text storage including its terminator, reporting size overflow as the\n## same fallible outcome as an allocation refusal. Callers initialize every byte.\nfunc terminated_buffer(length: usize) -> u8[]!:\n    let size = length +\? 1 else error(memory.exhausted, \"the text is too large\")\n    return try alloc u8[size]\n\n## Text built piece by piece. The builder keeps the allocator that was current when it\n## was created and grows in it, so it may cross `with` blocks and outlive them; `destroy`\n## gives its bytes back to that allocator.\npub struct Builder: io.Writer:\n    var data: u8[]\n    var used: usize\n    var owner: memory.Allocator\n\n    pub static func create(capacity: usize) -> Builder!:\n        return Builder(data = try alloc u8[capacity if capacity > 0 else 64], used = 0, owner = memory.allocator)\n\n    ## Ensure room for this many additional bytes and the NUL terminator. Growth\n    ## uses the original allocator and preserves the old text if allocation fails.\n    ## Growth invalidates borrowed views; a destroyed builder reports io.closed.\n    pub mutating func reserve(additional: usize) -> !:\n        if self.data.length == 0:\n            error(io.closed, \"the string builder is destroyed\")\n        let total = self.used +\? additional else error(memory.exhausted, \"the builder size overflows\")\n        let required = total +\? 1 else error(memory.exhausted, \"the builder size overflows\")\n        if required <= self.data.length:\n            return\n        var capacity = self.data.length *\? 2 else required\n        if capacity < required:\n            capacity = required\n        with self.owner:\n            self.data = try memory.grow(self.data, capacity)\n\n    ## Append bytes, including a view into this builder's current text. Preserve a\n    ## self-view's offset before growth, then rebase it if the allocation moves.\n    ## Aliased input must be wholly inside the initialized text, not spare capacity.\n    pub mutating func write(data: const u8[]) -> usize!:\n        if self.data.length == 0:\n            error(io.closed, \"the string builder is destroyed\")\n        if data.length == 0:\n            return 0\n        let start = (usize)self.data.data\n        let source = (usize)data.data\n        var offset: usize\? = none\n        if source >= start and source - start < self.data.length:\n            let relative = source - start\n            if relative > self.used or data.length > self.used - relative:\n                error(io.invalid_buffer, \"the builder input is outside its initialized text\")\n            offset = relative\n        try self.reserve(data.length)\n        if let relative = offset:\n            memory.move(self.data[self.used..], self.data[relative..], data.length)\n        else:\n            memory.move(self.data[self.used..], data, data.length)\n        self.used += data.length\n        return data.length\n\n    pub mutating func put(text: str) -> !:\n        discard(try self.write(text.bytes))\n\n    ## The text so far, NUL-terminated in the buffer: a borrowed view, invalid after\n    ## write, clear, growing reserve, or destroy. A destroyed builder has an empty view.\n    pub mutating func view() -> str:\n        if self.used < self.data.length:\n            self.data[self.used] = 0\n        return (str)self.data[..<self.used]\n\n    pub mutating func clear():\n        self.used = 0\n\n    ## Give the bytes back; the builder is empty and holds nothing.\n    pub mutating func destroy():\n        if self.data.length > 0:\n            free(self.data) in self.owner\n        var empty: u8[]\n        self.data = empty\n        self.used = 0\n", 8698})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"paths", 5}), .text = ((lb_str){"## File system paths as text, with `/` as the separator.\n\nimport memory\nimport strings\n\npub func is_absolute(path: str) -> bool:\n    return path.length > 0 and path.bytes[0] == '/'\n\n## Everything up to the last separator, or `.` when there is none.\npub func directory(path: str) -> str:\n    let cut = strings.last(path, '/') else return \".\"\n    if cut == 0:\n        return \"/\"\n    return (str)path.bytes[..<cut]\n\n## The last component.\npub func base(path: str) -> str:\n    let cut = strings.last(path, '/') else return path\n    return (str)path.bytes[cut + 1..]\n\n## The extension with its dot, or the empty text.\npub func extension(path: str) -> str:\n    let name = base(path)\n    let dot = strings.last(name, '.') else return \"\"\n    if dot == 0:\n        return \"\"\n    return (str)name.bytes[dot..]\n\n## The last component without its extension.\npub func stem(path: str) -> str:\n    let name = base(path)\n    let ext = extension(name)\n    return (str)name.bytes[..<name.length - ext.length]\n\n## `left/right`, in the current allocator; an absolute `right` wins.\npub func join(left: str, right: str) -> str!:\n    if is_absolute(right) or left.length == 0:\n        return try strings.copy(right)\n    let out = try alloc u8[left.length + right.length + 2]\n    var n: usize = 0\n    memory.copy(out, left.bytes, left.length)\n    n = left.length\n    if left.bytes[left.length - 1] != '/':\n        out[n] = '/'\n        n += 1\n    memory.copy(out[n..], right.bytes, right.length)\n    n += right.length\n    out[n] = 0\n    return (str)out[..<n]\n", 1533})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"math", 4}), .text = ((lb_str){"## The mathematical functions of the standard library (\302\24716.6): `import math` for\n## `math.sqrt(x)`, `from math import sqrt` for `sqrt(x)`. The float functions are the C\n## library's, declared here with the types Base gives them; the integer functions are Base.\nextern func c_floor as \"floor\"(x: f64) -> f64\nextern func c_ceil as \"ceil\"(x: f64) -> f64\nextern func c_round as \"round\"(x: f64) -> f64\nextern func c_trunc as \"trunc\"(x: f64) -> f64\nextern func c_sqrt as \"sqrt\"(x: f64) -> f64\nextern func c_cbrt as \"cbrt\"(x: f64) -> f64\nextern func c_hypot as \"hypot\"(x: f64, y: f64) -> f64\nextern func c_fmod as \"fmod\"(x: f64, y: f64) -> f64\nextern func c_pow as \"pow\"(x: f64, y: f64) -> f64\nextern func c_exp as \"exp\"(x: f64) -> f64\nextern func c_exp2 as \"exp2\"(x: f64) -> f64\nextern func c_log as \"log\"(x: f64) -> f64\nextern func c_log2 as \"log2\"(x: f64) -> f64\nextern func c_log10 as \"log10\"(x: f64) -> f64\nextern func c_sin as \"sin\"(x: f64) -> f64\nextern func c_cos as \"cos\"(x: f64) -> f64\nextern func c_tan as \"tan\"(x: f64) -> f64\nextern func c_asin as \"asin\"(x: f64) -> f64\nextern func c_acos as \"acos\"(x: f64) -> f64\nextern func c_atan as \"atan\"(x: f64) -> f64\nextern func c_atan2 as \"atan2\"(y: f64, x: f64) -> f64\nextern func c_sinh as \"sinh\"(x: f64) -> f64\nextern func c_cosh as \"cosh\"(x: f64) -> f64\nextern func c_tanh as \"tanh\"(x: f64) -> f64\nextern func c_log1p as \"log1p\"(x: f64) -> f64\nextern func c_expm1 as \"expm1\"(x: f64) -> f64\nextern func c_fma as \"fma\"(x: f64, y: f64, z: f64) -> f64\nextern func c_nextafter as \"nextafter\"(x: f64, toward: f64) -> f64\nextern func c_frexp as \"frexp\"(x: f64, out exponent: i32) -> f64\nextern func c_scalbn as \"scalbn\"(x: f64, exponent: i32) -> f64\nextern func c_modf as \"modf\"(x: f64, out integral: f64) -> f64\nextern func c_remainder as \"remainder\"(x: f64, y: f64) -> f64\n\npub let pi: f64 = 3.141592653589793\npub let tau: f64 = 6.283185307179586\npub let e: f64 = 2.718281828459045\n## Built from bits so that no constant expression needs to overflow.\npub let infinity: f64 = f64.bits(9218868437227405312)\npub let nan: f64 = f64.bits(9221120237041090560)\n\nlet sign_mask: u64 = 0x8000000000000000\nlet magnitude_mask: u64 = 0x7fffffffffffffff\nlet exponent_mask: u64 = 0x7ff0000000000000\n\n## Rounding: `floor` toward negative infinity, `ceil` toward positive, `round` to the\n## nearest with halves away from zero, `trunc` toward zero.\npub func floor(x: f64) -> f64:\n    return c_floor(x)\npub func ceil(x: f64) -> f64:\n    return c_ceil(x)\npub func round(x: f64) -> f64:\n    return c_round(x)\npub func trunc(x: f64) -> f64:\n    return c_trunc(x)\n\npub func sqrt(x: f64) -> f64:\n    return c_sqrt(x)\npub func cbrt(x: f64) -> f64:\n    return c_cbrt(x)\n## `sqrt(x * x + y * y)` without overflow in the squares.\npub func hypot(x: f64, y: f64) -> f64:\n    return c_hypot(x, y)\n## The remainder of `x / y` with the sign of `x`, as C's `fmod`.\npub func mod(x: f64, y: f64) -> f64:\n    return c_fmod(x, y)\npub func pow(x: f64, y: f64) -> f64:\n    return c_pow(x, y)\npub func exp(x: f64) -> f64:\n    return c_exp(x)\npub func exp2(x: f64) -> f64:\n    return c_exp2(x)\npub func log(x: f64) -> f64:\n    return c_log(x)\npub func log2(x: f64) -> f64:\n    return c_log2(x)\npub func log10(x: f64) -> f64:\n    return c_log10(x)\n\n## Natural logarithm of `1 + x`, retaining accuracy when adding `x` to one would\n## round it away. At -1 the result is negative infinity; below -1 it is NaN.\npub func log1p(x: f64) -> f64:\n    return c_log1p(x)\n\n## `exp(x) - 1` without cancellation near zero. Signed zero is preserved.\npub func expm1(x: f64) -> f64:\n    return c_expm1(x)\n\n## Multiply `x * y` and add `z` with one final rounding, rather than rounding the\n## product first. Uses the host's floating-point rounding mode.\npub func fma(x: f64, y: f64, z: f64) -> f64:\n    return c_fma(x, y, z)\n\n## The adjacent representable value toward `toward`; equal arguments return\n## `toward`, including its zero sign. A NaN argument produces NaN.\npub func nextafter(x: f64, toward: f64) -> f64:\n    return c_nextafter(x, toward)\n\n## The adjacent representable value toward positive infinity. Positive infinity\n## stays infinite; either zero becomes the smallest positive subnormal.\npub func next_up(x: f64) -> f64:\n    return c_nextafter(x, infinity)\n\n## The adjacent representable value toward negative infinity. Negative infinity\n## stays infinite; either zero becomes the smallest negative subnormal.\npub func next_down(x: f64) -> f64:\n    return c_nextafter(x, copysign(infinity, -1.0))\n\n## Split `x` into `(fraction, exponent)` such that `x = fraction * 2**exponent`.\n## A finite nonzero fraction has magnitude in [0.5, 1). Zero, infinity and NaN\n## are returned unchanged with exponent zero, avoiding an unspecified C exponent.\npub func frexp(x: f64) -> (f64, i32):\n    if x == 0.0 or not is_finite(x):\n        return (x, 0)\n    return c_frexp(x)\n\n## Scale by an integer power of two, without forming that power as an intermediate\n## float. Overflow/underflow follow the host rounding mode; signed zero survives.\npub func scalbn(x: f64, exponent: i32) -> f64:\n    return c_scalbn(x, exponent)\n\n## `(fractional, integral)` parts, both with the sign of `x`; the integral part\n## truncates toward zero. Infinity has a signed-zero fraction; NaN gives two NaNs.\npub func modf(x: f64) -> (f64, f64):\n    return c_modf(x)\n\n## `x - n*y` for the nearest integer `n` to `x/y`, with ties choosing even `n`.\n## This differs from `mod`, which truncates the quotient. Zero has the sign of `x`;\n## a zero divisor or infinite dividend produces NaN.\npub func remainder(x: f64, y: f64) -> f64:\n    return c_remainder(x, y)\n\npub func sin(x: f64) -> f64:\n    return c_sin(x)\npub func cos(x: f64) -> f64:\n    return c_cos(x)\npub func tan(x: f64) -> f64:\n    return c_tan(x)\npub func asin(x: f64) -> f64:\n    return c_asin(x)\npub func acos(x: f64) -> f64:\n    return c_acos(x)\npub func atan(x: f64) -> f64:\n    return c_atan(x)\n## The angle of the point `(x, y)`, in all four quadrants.\npub func atan2(y: f64, x: f64) -> f64:\n    return c_atan2(y, x)\npub func sinh(x: f64) -> f64:\n    return c_sinh(x)\npub func cosh(x: f64) -> f64:\n    return c_cosh(x)\npub func tanh(x: f64) -> f64:\n    return c_tanh(x)\n\n## True for quiet and signaling NaNs, independent of sign and payload.\npub func is_nan(x: f64) -> bool:\n    return (x.bits() & magnitude_mask) > exponent_mask\n## True for zeros, subnormals and normal finite values. Classification inspects the\n## representation and performs no floating-point arithmetic on a signaling NaN.\npub func is_finite(x: f64) -> bool:\n    return (x.bits() & exponent_mask) != exponent_mask\n## True only for positive or negative infinity.\npub func is_infinite(x: f64) -> bool:\n    return (x.bits() & magnitude_mask) == exponent_mask\n## Whether the sign bit is set, including negative zero and signed NaNs.\npub func signbit(x: f64) -> bool:\n    return (x.bits() & sign_mask) != 0\n## Clear the sign bit: negative zero becomes positive zero. NaN payload bits survive.\npub func abs(x: f64) -> f64:\n    return f64.bits(x.bits() & magnitude_mask)\n## The magnitude and payload of `magnitude` with the sign bit of `sign_source`.\npub func copysign(magnitude: f64, sign_source: f64) -> f64:\n    return f64.bits((magnitude.bits() & magnitude_mask) | (sign_source.bits() & sign_mask))\n## `-1.0` or `1.0` for nonzero numbers; zero and NaN are returned unchanged.\npub func sign(x: f64) -> f64:\n    if is_nan(x):\n        return x\n    if x < 0.0:\n        return -1.0\n    if x > 0.0:\n        return 1.0\n    return x\n## Minimum with NaN propagation (left NaN wins if both are NaNs). Negative zero\n## wins over positive zero; a selected NaN retains its original bits.\npub func min(a: f64, b: f64) -> f64:\n    if is_nan(a):\n        return a\n    if is_nan(b):\n        return b\n    if a == 0.0 and b == 0.0:\n        return f64.bits(a.bits() | b.bits())\n    return a if a < b else b\n## Maximum with NaN propagation (left NaN wins if both are NaNs). Positive zero\n## wins over negative zero; a selected NaN retains its original bits.\npub func max(a: f64, b: f64) -> f64:\n    if is_nan(a):\n        return a\n    if is_nan(b):\n        return b\n    if a == 0.0 and b == 0.0:\n        return f64.bits(a.bits() & b.bits())\n    return a if a > b else b\n## Restrict `x` to inclusive ordered bounds. Reversed or NaN bounds trap. An input\n## NaN or an input equal to a bound is returned unchanged, including its zero sign.\npub func clamp(x: f64, low: f64, high: f64) -> f64:\n    assert(low <= high)\n    if is_nan(x):\n        return x\n    return low if x < low else (high if x > high else x)\n\n## The integer functions. `//` and `%` truncate toward zero as C does (\302\2477.2); these two\n## floor, so `div_floor(-7, 2)` is `-4` and `mod_floor(-7, 2)` is `1`.\npub func div_floor(a: i64, b: i64) -> i64:\n    let q = a // b\n    if (a % b != 0) and ((a < 0) != (b < 0)):\n        return q - 1\n    return q\npub func mod_floor(a: i64, b: i64) -> i64:\n    let r = a % b\n    if r != 0 and ((r < 0) != (b < 0)):\n        return r + b\n    return r\npub func iabs(a: i64) -> i64:\n    return 0 - a if a < 0 else a\n## Absolute value, or none for the minimum i64 whose positive magnitude cannot fit.\npub func checked_iabs(a: i64) -> i64\?:\n    if a < 0:\n        return 0 -\? a\n    return a\n## Floor division, or none for a zero divisor or a quotient outside i64.\npub func checked_div_floor(a: i64, b: i64) -> i64\?:\n    if b == 0 or (a == -9223372036854775808 and b == -1):\n        return none\n    return div_floor(a, b)\n## Remainder with the divisor's sign, or none for a zero divisor. The minimum i64\n## modulo -1 is zero even though its quotient cannot be represented.\npub func checked_mod_floor(a: i64, b: i64) -> i64\?:\n    if b == 0:\n        return none\n    if b == -1:\n        return 0\n    return mod_floor(a, b)\npub func imin(a: i64, b: i64) -> i64:\n    return a if a < b else b\npub func imax(a: i64, b: i64) -> i64:\n    return a if a > b else b\n## Restrict `x` to inclusive ordered bounds. Reversed bounds trap.\npub func iclamp(x: i64, low: i64, high: i64) -> i64:\n    assert(low <= high)\n    return low if x < low else (high if x > high else x)\n", 10111})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"math32", 6}), .text = ((lb_str){"## Single-precision mathematics. `math32` has the floating-point operations of\n## `math`, with f32 arguments and results and the same special-value contracts.\n## Elementary functions call the host's single-precision libm entry points directly;\n## they do not compute in f64 and then introduce an extra rounding step.\nextern func c_floor as \"floorf\"(x: f32) -> f32\nextern func c_ceil as \"ceilf\"(x: f32) -> f32\nextern func c_round as \"roundf\"(x: f32) -> f32\nextern func c_trunc as \"truncf\"(x: f32) -> f32\nextern func c_sqrt as \"sqrtf\"(x: f32) -> f32\nextern func c_cbrt as \"cbrtf\"(x: f32) -> f32\nextern func c_hypot as \"hypotf\"(x: f32, y: f32) -> f32\nextern func c_fmod as \"fmodf\"(x: f32, y: f32) -> f32\nextern func c_pow as \"powf\"(x: f32, y: f32) -> f32\nextern func c_exp as \"expf\"(x: f32) -> f32\nextern func c_exp2 as \"exp2f\"(x: f32) -> f32\nextern func c_log as \"logf\"(x: f32) -> f32\nextern func c_log2 as \"log2f\"(x: f32) -> f32\nextern func c_log10 as \"log10f\"(x: f32) -> f32\nextern func c_sin as \"sinf\"(x: f32) -> f32\nextern func c_cos as \"cosf\"(x: f32) -> f32\nextern func c_tan as \"tanf\"(x: f32) -> f32\nextern func c_asin as \"asinf\"(x: f32) -> f32\nextern func c_acos as \"acosf\"(x: f32) -> f32\nextern func c_atan as \"atanf\"(x: f32) -> f32\nextern func c_atan2 as \"atan2f\"(y: f32, x: f32) -> f32\nextern func c_sinh as \"sinhf\"(x: f32) -> f32\nextern func c_cosh as \"coshf\"(x: f32) -> f32\nextern func c_tanh as \"tanhf\"(x: f32) -> f32\nextern func c_log1p as \"log1pf\"(x: f32) -> f32\nextern func c_expm1 as \"expm1f\"(x: f32) -> f32\nextern func c_fma as \"fmaf\"(x: f32, y: f32, z: f32) -> f32\nextern func c_nextafter as \"nextafterf\"(x: f32, toward: f32) -> f32\nextern func c_frexp as \"frexpf\"(x: f32, out exponent: i32) -> f32\nextern func c_scalbn as \"scalbnf\"(x: f32, exponent: i32) -> f32\nextern func c_modf as \"modff\"(x: f32, out integral: f32) -> f32\nextern func c_remainder as \"remainderf\"(x: f32, y: f32) -> f32\n\npub let pi: f32 = 3.141592653589793\npub let tau: f32 = 6.283185307179586\npub let e: f32 = 2.718281828459045\n## Built from bits so that no constant expression needs to overflow.\npub let infinity: f32 = f32.bits(2139095040)\npub let nan: f32 = f32.bits(2143289344)\n\nlet sign_mask: u32 = 0x80000000\nlet magnitude_mask: u32 = 0x7fffffff\nlet exponent_mask: u32 = 0x7f800000\n\n## Rounding: `floor` toward negative infinity, `ceil` toward positive, `round` to the\n## nearest with halves away from zero, `trunc` toward zero.\npub func floor(x: f32) -> f32:\n    return c_floor(x)\npub func ceil(x: f32) -> f32:\n    return c_ceil(x)\npub func round(x: f32) -> f32:\n    return c_round(x)\npub func trunc(x: f32) -> f32:\n    return c_trunc(x)\n\npub func sqrt(x: f32) -> f32:\n    return c_sqrt(x)\npub func cbrt(x: f32) -> f32:\n    return c_cbrt(x)\n## `sqrt(x * x + y * y)` without overflow in the squares.\npub func hypot(x: f32, y: f32) -> f32:\n    return c_hypot(x, y)\n## The remainder of `x / y` with the sign of `x`, as C's `fmod`.\npub func mod(x: f32, y: f32) -> f32:\n    return c_fmod(x, y)\npub func pow(x: f32, y: f32) -> f32:\n    return c_pow(x, y)\npub func exp(x: f32) -> f32:\n    return c_exp(x)\npub func exp2(x: f32) -> f32:\n    return c_exp2(x)\npub func log(x: f32) -> f32:\n    return c_log(x)\npub func log2(x: f32) -> f32:\n    return c_log2(x)\npub func log10(x: f32) -> f32:\n    return c_log10(x)\n\n## Natural logarithm of `1 + x`, retaining accuracy when adding `x` to one would\n## round it away. At -1 the result is negative infinity; below -1 it is NaN.\npub func log1p(x: f32) -> f32:\n    return c_log1p(x)\n\n## `exp(x) - 1` without cancellation near zero. Signed zero is preserved.\npub func expm1(x: f32) -> f32:\n    return c_expm1(x)\n\n## Multiply `x * y` and add `z` with one final rounding, rather than rounding the\n## product first. Uses the host's floating-point rounding mode.\npub func fma(x: f32, y: f32, z: f32) -> f32:\n    return c_fma(x, y, z)\n\n## The adjacent representable value toward `toward`; equal arguments return\n## `toward`, including its zero sign. A NaN argument produces NaN.\npub func nextafter(x: f32, toward: f32) -> f32:\n    return c_nextafter(x, toward)\n\n## The adjacent representable value toward positive infinity. Positive infinity\n## stays infinite; either zero becomes the smallest positive subnormal.\npub func next_up(x: f32) -> f32:\n    return c_nextafter(x, infinity)\n\n## The adjacent representable value toward negative infinity. Negative infinity\n## stays infinite; either zero becomes the smallest negative subnormal.\npub func next_down(x: f32) -> f32:\n    return c_nextafter(x, copysign(infinity, -1.0))\n\n## Split `x` into `(fraction, exponent)` such that `x = fraction * 2**exponent`.\n## A finite nonzero fraction has magnitude in [0.5, 1). Zero, infinity and NaN\n## are returned unchanged with exponent zero, avoiding an unspecified C exponent.\npub func frexp(x: f32) -> (f32, i32):\n    if x == 0.0 or not is_finite(x):\n        return (x, 0)\n    return c_frexp(x)\n\n## Scale by an integer power of two, without forming that power as an intermediate\n## float. Overflow/underflow follow the host rounding mode; signed zero survives.\npub func scalbn(x: f32, exponent: i32) -> f32:\n    return c_scalbn(x, exponent)\n\n## `(fractional, integral)` parts, both with the sign of `x`; the integral part\n## truncates toward zero. Infinity has a signed-zero fraction; NaN gives two NaNs.\npub func modf(x: f32) -> (f32, f32):\n    return c_modf(x)\n\n## `x - n*y` for the nearest integer `n` to `x/y`, with ties choosing even `n`.\n## This differs from `mod`, which truncates the quotient. Zero has the sign of `x`;\n## a zero divisor or infinite dividend produces NaN.\npub func remainder(x: f32, y: f32) -> f32:\n    return c_remainder(x, y)\n\npub func sin(x: f32) -> f32:\n    return c_sin(x)\npub func cos(x: f32) -> f32:\n    return c_cos(x)\npub func tan(x: f32) -> f32:\n    return c_tan(x)\npub func asin(x: f32) -> f32:\n    return c_asin(x)\npub func acos(x: f32) -> f32:\n    return c_acos(x)\npub func atan(x: f32) -> f32:\n    return c_atan(x)\n## The angle of the point `(x, y)`, in all four quadrants.\npub func atan2(y: f32, x: f32) -> f32:\n    return c_atan2(y, x)\npub func sinh(x: f32) -> f32:\n    return c_sinh(x)\npub func cosh(x: f32) -> f32:\n    return c_cosh(x)\npub func tanh(x: f32) -> f32:\n    return c_tanh(x)\n\n## True for quiet and signaling NaNs, independent of sign and payload.\npub func is_nan(x: f32) -> bool:\n    return (x.bits() & magnitude_mask) > exponent_mask\n## True for zeros, subnormals and normal finite values. Classification inspects the\n## representation and performs no floating-point arithmetic on a signaling NaN.\npub func is_finite(x: f32) -> bool:\n    return (x.bits() & exponent_mask) != exponent_mask\n## True only for positive or negative infinity.\npub func is_infinite(x: f32) -> bool:\n    return (x.bits() & magnitude_mask) == exponent_mask\n## Whether the sign bit is set, including negative zero and signed NaNs.\npub func signbit(x: f32) -> bool:\n    return (x.bits() & sign_mask) != 0\n## Clear the sign bit: negative zero becomes positive zero. NaN payload bits survive.\npub func abs(x: f32) -> f32:\n    return f32.bits(x.bits() & magnitude_mask)\n## The magnitude and payload of `magnitude` with the sign bit of `sign_source`.\npub func copysign(magnitude: f32, sign_source: f32) -> f32:\n    return f32.bits((magnitude.bits() & magnitude_mask) | (sign_source.bits() & sign_mask))\n## `-1.0` or `1.0` for nonzero numbers; zero and NaN are returned unchanged.\npub func sign(x: f32) -> f32:\n    if is_nan(x):\n        return x\n    if x < 0.0:\n        return -1.0\n    if x > 0.0:\n        return 1.0\n    return x\n## Minimum with NaN propagation (left NaN wins if both are NaNs). Negative zero\n## wins over positive zero; a selected NaN retains its original bits.\npub func min(a: f32, b: f32) -> f32:\n    if is_nan(a):\n        return a\n    if is_nan(b):\n        return b\n    if a == 0.0 and b == 0.0:\n        return f32.bits(a.bits() | b.bits())\n    return a if a < b else b\n## Maximum with NaN propagation (left NaN wins if both are NaNs). Positive zero\n## wins over negative zero; a selected NaN retains its original bits.\npub func max(a: f32, b: f32) -> f32:\n    if is_nan(a):\n        return a\n    if is_nan(b):\n        return b\n    if a == 0.0 and b == 0.0:\n        return f32.bits(a.bits() & b.bits())\n    return a if a > b else b\n## Restrict `x` to inclusive ordered bounds. Reversed or NaN bounds trap. An input\n## NaN or an input equal to a bound is returned unchanged, including its zero sign.\npub func clamp(x: f32, low: f32, high: f32) -> f32:\n    assert(low <= high)\n    if is_nan(x):\n        return x\n    return low if x < low else (high if x > high else x)\n", 8620})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"time", 4}), .text = ((lb_str){"import platform\n\nextern func clock_gettime(clock: i32, out_time: Stamp*) -> i32\nextern func c_time as \"time\"(out_time: void*\?) -> i64\n\nextern struct Stamp:\n    seconds: i64\n    nanoseconds: i64\n\n## `CLOCK_MONOTONIC`: 6 on macOS, 1 on Linux; `CLOCK_REALTIME` is 0 on both.\nlet monotonic: i32 = 6 if platform.macos else 1\nlet realtime: i32 = 0\n\n## Nanoseconds from an arbitrary origin, never going backwards.\npub func now() -> u64:\n    var stamp = Stamp(seconds = 0, nanoseconds = 0)\n    discard(clock_gettime(monotonic, &stamp))\n    return (u64)stamp.seconds * 1000000000 + (u64)stamp.nanoseconds\n\n## Seconds since the Unix epoch.\npub func unix() -> i64:\n    return c_time(none)\n\n## Nanoseconds elapsed since `start`, from `now()`.\npub func since(start: u64) -> u64:\n    let current = now()\n    return current - start if current > start else 0\n", 843})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"os", 2}), .text = ((lb_str){"## The operating system's view of the process (\302\24716.6): its environment, working\n## directory, identity, and host. Text comes back as `str` views of C storage that the\n## system owns; copy what must outlive the next call.\nimport c\nimport memory\nimport platform\n\nextern func getenv(variable: c.str) -> c.str\?\nextern func setenv(variable: c.str, value: c.str, overwrite: i32) -> i32\nextern func unsetenv(variable: c.str) -> i32\nextern func getcwd(buffer: u8*, size: usize) -> c.str\?\nextern func chdir(path: c.str) -> i32\nextern func getpid() -> i32\nextern func getppid() -> i32\nextern func gethostname(buffer: u8*, size: usize) -> i32\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func sysconf(option: i32) -> i64\nextern func getpagesize() -> i32\n\npub let failed: ErrorCode = ErrorCode.package(12)\n\n## The target, as constants a program branches on: `if os.arm64:`, `if os.linux and\n## os.x86_64:` (\302\24719.5); the compiler decides them from `--target`, so the branch a target\n## rules out is pruned (\302\24719.6).\npub let arm64: bool = platform.arm64\npub let x86_64: bool = platform.x86_64\npub let macos: bool = platform.macos\npub let linux: bool = platform.linux\npub let windows: bool = platform.windows\npub let posix: bool = platform.posix\npub let pointer_bits: u32 = platform.pointer_bits\npub let name: str = platform.name\n## The instruction-set level the program was compiled for (`--cpu`, \302\24719.5): on x86-64, 1\n## to 4 for x86-64-v1 to v4; on arm64, 1 for NEON, 2 for SVE.\npub let cpu_level: u32 = platform.cpu_level\n\n## The instruction-set level of the processor this program runs on, in the same scale:\n## what it may dispatch to at run time. On x86-64 `cpuid` answers; on arm64 the level is\n## NEON until the system reports SVE.\npub func cpu_level_running() -> u32:\n    if platform.x86_64:\n        return x86_level()\n    return 1\n\n## x86-64: SSE4.2 and POPCNT make v2; AVX2, FMA, and BMI2 make v3; AVX-512F makes v4.\nfunc x86_level() -> u32:\n    var c1: u32 = 0\n    var b7: u32 = 0\n    asm x86_64 (in(\"eax\") 1u32, out(\"ecx\") c1, out(\"eax\") _, out(\"ebx\") _, out(\"edx\") _, options(nostack)):\n        cpuid\n    asm x86_64 (in(\"eax\") 7u32, in(\"ecx\") 0u32, out(\"ebx\") b7, out(\"eax\") _, out(\"ecx\") _, out(\"edx\") _, options(nostack)):\n        cpuid\n    let sse42 = (c1 & (1 << 20)) != 0\n    let popcnt = (c1 & (1 << 23)) != 0\n    let fma = (c1 & (1 << 12)) != 0\n    let avx2 = (b7 & (1 << 5)) != 0\n    let bmi2 = (b7 & (1 << 8)) != 0\n    let avx512f = (b7 & (1 << 16)) != 0\n    if not (sse42 and popcnt):\n        return 1\n    if not (avx2 and fma and bmi2):\n        return 2\n    return 4 if avx512f else 3\n\n## `_SC_NPROCESSORS_ONLN`: 58 on macOS, 84 on Linux.\nlet processors_online: i32 = 58 if platform.macos else 84\n\n## The processors available to this process, at least one.\npub func cpus() -> u32:\n    let n = sysconf(processors_online)\n    return (u32)n if n > 0 else 1\n\npub func page_size() -> usize:\n    return (usize)getpagesize()\n\n## The value of an environment variable, or none when it is not set.\npub func env(variable: c.str) -> str\?:\n    let value = getenv(variable) else return none\n    return (str)value\n\n## Set an environment variable for this process and the ones it starts.\npub func set_env(variable: c.str, value: c.str) -> !:\n    if setenv(variable, value, 1) != 0:\n        error(failed, \"the environment variable cannot be set\")\n\npub func unset_env(variable: c.str) -> !:\n    if unsetenv(variable) != 0:\n        error(failed, \"the environment variable cannot be unset\")\n\n## The working directory, in storage from the current allocator.\npub func cwd() -> str!:\n    let buffer = try alloc u8[4096]\n    let found = getcwd(buffer.data, buffer.length)\n    if found == none:\n        free(buffer)\n        error(failed, \"the working directory cannot be read\")\n    let path = found else trap(\"unreachable\")\n    return (str)path\n\npub func change_dir(path: c.str) -> !:\n    if chdir(path) != 0:\n        error(failed, \"the directory cannot be entered\")\n\npub func pid() -> i32:\n    return getpid()\n\npub func parent_pid() -> i32:\n    return getppid()\n\n## The host's name, in storage from the current allocator.\npub func hostname() -> str!:\n    let buffer = try alloc u8[256]\n    if gethostname(buffer.data, buffer.length) != 0:\n        free(buffer)\n        error(failed, \"the host name cannot be read\")\n    var n: usize = 0\n    while n < buffer.length and buffer[n] != 0:\n        n += 1\n    return (str)buffer[..<n]\n\n## Stop the process with `code`, running no deferred work.\npub func exit(code: i32) -> never:\n    c_exit(code)\n", 4538})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"testing", 7}), .text = ((lb_str){"## What a Base test runs under (\302\24716.5): a fixed-buffer allocator made current for\n## each test, a deterministic seed, and assertions that name what differed.\n\nimport memory\nfrom memory import Allocator, FixedBuffer\n\nvar arena_bytes: u8[1048576]\nvar arena: FixedBuffer\nvar saved: Allocator\nvar current_seed: u64 = 1\n\n## Called by the runner before each test.\npub func begin(index: u64):\n    arena = FixedBuffer.over(arena_bytes)\n    saved = memory.allocator\n    memory.allocator = &arena\n    current_seed = index * 2654435761 + 1\n\n## Called by the runner after each test.\npub func end():\n    memory.allocator = saved\n\n## A seed that is the same on every run of the same test.\npub func seed() -> u64:\n    return current_seed\n\n## The next pseudo-random value from the seed, and the seed advanced.\npub func random() -> u64:\n    var x = current_seed\n    x = x ^ (x << 13)\n    x = x ^ (x >> 7)\n    x = x ^ (x << 17)\n    current_seed = x\n    return x\n\npub func expect(condition: bool, message: str):\n    if not condition:\n        trap(message)\n\npub func expect_equal(actual: i64, expected: i64, message: str):\n    if actual != expected:\n        print(f\"expected {expected}, got {actual}: {message}\")\n        trap(message)\n\npub func expect_text(actual: str, expected: str, message: str):\n    if actual != expected:\n        print(f\"expected `{expected}`, got `{actual}`: {message}\")\n        trap(message)\n", 1397})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"net", 3}), .text = ((lb_str){"import c\nimport platform\nfrom io import Writer\n\nextern func socket(domain: i32, kind: i32, protocol: i32) -> i32\nextern func bind(descriptor: i32, address: const SocketAddress*, length: u32) -> i32\nextern func listen(descriptor: i32, backlog: i32) -> i32\nextern func accept(descriptor: i32, address: SocketAddress*\?, length: u32*\?) -> i32\nextern func connect(descriptor: i32, address: const SocketAddress*, length: u32) -> i32\nextern func send(descriptor: i32, data: const void*, length: usize, flags: i32) -> isize\nextern func recv(descriptor: i32, buffer: void*, length: usize, flags: i32) -> isize\nextern func sendto(descriptor: i32, data: const void*, length: usize, flags: i32, address: const SocketAddress*, address_length: u32) -> isize\nextern func recvfrom(descriptor: i32, buffer: void*, length: usize, flags: i32, address: SocketAddress*\?, address_length: u32*\?) -> isize\nextern func close(descriptor: i32) -> i32\nextern func setsockopt(descriptor: i32, level: i32, option: i32, value: const void*, length: u32) -> i32\nextern func getsockname(descriptor: i32, address: SocketAddress*, length: u32*) -> i32\nextern func getaddrinfo(host: c.str, service: c.str\?, hints: const AddressInfo*\?, result: AddressInfo*\?*) -> i32\nextern func freeaddrinfo(info: AddressInfo*)\n\n## `sockaddr_in`: 16 bytes everywhere; macOS splits the first two into a length and a\n## one-byte family, Linux keeps a two-byte family. `family_word` reads and writes it.\nextern struct SocketAddress:\n    head: u16\n    port: u16\n    address: u32\n    zero: u8[8]\n\n## The first two bytes of `sockaddr_in` as one little-endian word: on macOS the length\n## byte (16) comes first and the family byte second, on Linux the family fills both.\nfunc family_word(family: u8) -> u16:\n    if platform.macos:\n        return (u16)16 | ((u16)family << 8)\n    return (u16)family\n\n## `addrinfo`: macOS puts the canonical name before the address, Linux after it.\nextern struct AddressInfo:\n    flags: i32\n    family: i32\n    kind: i32\n    protocol: i32\n    address_length: u32\n    fifth: void*\?\n    sixth: void*\?\n    next: AddressInfo*\?\n\nfunc info_address(info: AddressInfo*) -> SocketAddress*\?:\n    let raw = info.sixth if platform.macos else info.fifth\n    let p = raw else return none\n    return (SocketAddress*)p\n\nlet inet: i32 = 2\nlet stream: i32 = 1\nlet datagram: i32 = 2\n## `SOL_SOCKET` and `SO_REUSEADDR`: 65535 and 4 on macOS, 1 and 2 on Linux.\nlet socket_level: i32 = 65535 if platform.macos else 1\nlet reuse_address: i32 = 4 if platform.macos else 2\n## A write to a socket the peer closed answers an error, never the process's death:\n## macOS marks the socket (`SO_NOSIGPIPE`, 4130), Linux marks the send (`MSG_NOSIGNAL`,\n## 16384).\nlet no_sigpipe_option: i32 = 4130\nlet send_flags: i32 = 0 if platform.macos else 16384\n\npub let failed: ErrorCode = ErrorCode.package(9)\npub let closed: ErrorCode = ErrorCode.package(10)\npub let unknown_host: ErrorCode = ErrorCode.package(11)\n\n## An IPv4 address and port, both in host order.\npub struct Address:\n    pub var ip: u32\n    pub var port: u16\n\n    pub static func loopback(port: u16) -> Address:\n        return Address(ip = 2130706433, port = port)\n\n    pub static func any(port: u16) -> Address:\n        return Address(ip = 0, port = port)\n\n    func raw() -> SocketAddress:\n        var zero: u8[8]\n        return SocketAddress(head = family_word(2), port = swap16(self.port), address = swap32(self.ip), zero = zero)\n\n    static func from_raw(raw: SocketAddress) -> Address:\n        return Address(ip = swap32(raw.address), port = swap16(raw.port))\n\n## Host to network byte order and back; the machine is little-endian.\nfunc swap16(value: u16) -> u16:\n    return (value << 8) | (value >> 8)\n\nfunc swap32(value: u32) -> u32:\n    return (value << 24) | ((value << 8) & 16711680) | ((value >> 8) & 65280) | (value >> 24)\n\n## The first usable IPv4 stream address of `host`. Resolution may block in the OS.\n## All resolver storage is released before returning, including malformed results.\npub func resolve(host: c.str, port: u16) -> Address!:\n    var hints = AddressInfo(flags = 0, family = inet, kind = stream, protocol = 0, address_length = 0, fifth = none, sixth = none, next = none)\n    var found: AddressInfo*\? = none\n    if getaddrinfo(host, none, &hints, &found) != 0:\n        error(unknown_host, \"unknown host\")\n    let info = found else error(unknown_host, \"unknown host\")\n    defer freeaddrinfo(info)\n    var current: AddressInfo*\? = info\n    while let entry = current:\n        if entry.family == inet and entry.kind == stream and entry.address_length >= sizeof(SocketAddress):\n            if let raw = info_address(entry):\n                var address = Address.from_raw(*raw)\n                address.port = port\n                return address\n        current = entry.next\n    error(unknown_host, \"the host has no usable IPv4 stream address\")\n\n## A bound TCP socket waiting for connections.\npub struct Listener:\n    var descriptor: i32\n\n    pub static func bind(address: Address) -> Listener!:\n        let fd = socket(inet, stream, 0)\n        if fd < 0:\n            error(failed, \"socket\")\n        var yes: i32 = 1\n        discard(setsockopt(fd, socket_level, reuse_address, &yes, 4))\n        let raw = address.raw()\n        if bind(fd, &raw, 16) != 0:\n            discard(close(fd))\n            error(failed, \"bind\")\n        if listen(fd, 16) != 0:\n            discard(close(fd))\n            error(failed, \"listen\")\n        return Listener(descriptor = fd)\n\n    ## The address the socket ended up with; a port of zero asked for any free one.\n    pub func address() -> Address:\n        var raw = SocketAddress(head = 0, port = 0, address = 0, zero = [0, 0, 0, 0, 0, 0, 0, 0])\n        var length: u32 = 16\n        discard(getsockname(self.descriptor, &raw, &length))\n        return Address.from_raw(raw)\n\n    pub func accept() -> Connection!:\n        var fd = accept(self.descriptor, none, none)\n        while fd < 0 and c.errno() == c.interrupted:\n            fd = accept(self.descriptor, none, none)\n        if fd < 0:\n            error(failed, \"accept\")\n        return Connection.over(fd)\n\n    pub func close():\n        discard(close(self.descriptor))\n\n## One TCP connection; it is a `Writer`.\npub struct Connection: Writer:\n    ## The socket, for callers that poll or pass it on.\n    pub var descriptor: i32\n    ## Whether the socket is marked against `SIGPIPE` (macOS); `write` marks it on first\n    ## use, so a connection built any other way than `over` is guarded too.\n    var guarded: bool\n\n    pub static func connect(address: Address) -> Connection!:\n        let fd = socket(inet, stream, 0)\n        if fd < 0:\n            error(failed, \"socket\")\n        let raw = address.raw()\n        if connect(fd, &raw, 16) != 0:\n            discard(close(fd))\n            error(failed, \"connect\")\n        return Connection.over(fd)\n\n    ## A connection over a socket the caller made (a `socketpair`, an inherited\n    ## descriptor): the socket is marked so that a write after the peer closed fails\n    ## instead of ending the process. Make the connection while the peer is still there:\n    ## macOS refuses the mark on a socket whose peer has already gone, and a write on\n    ## such a connection answers `closed` without sending.\n    pub static func over(descriptor: i32) -> Connection:\n        var connection = Connection(descriptor = descriptor, guarded = false)\n        discard(connection.guard())\n        return connection\n\n    ## Whether a write cannot raise `SIGPIPE`. Linux asks with every `send`\n    ## (`MSG_NOSIGNAL`); macOS marks the socket once (`SO_NOSIGPIPE`), and refuses the mark\n    ## with `EINVAL` on a socket whose peer has disconnected.\n    mutating func guard() -> bool:\n        if self.guarded:\n            return true\n        if not platform.macos:\n            self.guarded = true\n            return true\n        var yes: i32 = 1\n        if setsockopt(self.descriptor, socket_level, no_sigpipe_option, &yes, 4) == 0:\n            self.guarded = true\n        return self.guarded\n\n    ## Send every byte; a peer that closed is `closed`, never a signal.\n    pub mutating func write(data: const u8[]) -> usize!:\n        if not self.guard():\n            error(closed, \"the connection closed\")\n        var done: usize = 0\n        while done < data.length:\n            let n = send(self.descriptor, data[done..].data, data.length - done, send_flags)\n            if n < 0 and c.errno() == c.interrupted:\n                continue\n            if n <= 0:\n                error(closed, \"the connection closed\")\n            done += (usize)n\n        return done\n\n    ## Receive what is available, up to the buffer; zero means the peer closed.\n    pub func receive(buffer: u8[]) -> usize!:\n        var n = recv(self.descriptor, buffer.data, buffer.length, 0)\n        while n < 0 and c.errno() == c.interrupted:\n            n = recv(self.descriptor, buffer.data, buffer.length, 0)\n        if n < 0:\n            error(closed, \"the connection closed\")\n        return (usize)n\n\n    pub func close():\n        discard(close(self.descriptor))\n\n## A UDP socket.\npub struct Datagram:\n    var descriptor: i32\n\n    pub static func bind(address: Address) -> Datagram!:\n        let fd = socket(inet, datagram, 0)\n        if fd < 0:\n            error(failed, \"socket\")\n        let raw = address.raw()\n        if bind(fd, &raw, 16) != 0:\n            discard(close(fd))\n            error(failed, \"bind\")\n        return Datagram(descriptor = fd)\n\n    pub func address() -> Address:\n        var raw = SocketAddress(head = 0, port = 0, address = 0, zero = [0, 0, 0, 0, 0, 0, 0, 0])\n        var length: u32 = 16\n        discard(getsockname(self.descriptor, &raw, &length))\n        return Address.from_raw(raw)\n\n    pub func send_to(data: const u8[], address: Address) -> !:\n        let raw = address.raw()\n        var n = sendto(self.descriptor, data.data, data.length, 0, &raw, 16)\n        while n < 0 and c.errno() == c.interrupted:\n            n = sendto(self.descriptor, data.data, data.length, 0, &raw, 16)\n        if n < 0 or (usize)n != data.length:\n            error(failed, \"send\")\n\n    pub func receive_from(buffer: u8[]) -> (usize, Address)!:\n        var raw = SocketAddress(head = 0, port = 0, address = 0, zero = [0, 0, 0, 0, 0, 0, 0, 0])\n        var length: u32 = 16\n        var n = recvfrom(self.descriptor, buffer.data, buffer.length, 0, &raw, &length)\n        while n < 0 and c.errno() == c.interrupted:\n            length = 16\n            n = recvfrom(self.descriptor, buffer.data, buffer.length, 0, &raw, &length)\n        if n < 0:\n            error(failed, \"receive\")\n        return ((usize)n, Address.from_raw(raw))\n\n    pub func close():\n        discard(close(self.descriptor))\n", 10707})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"debug", 5}), .text = ((lb_str){"import c\nimport memory\n\nextern func getenv(name: c.str) -> c.str\?\nextern func c_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func c_exit as \"exit\"(code: i32) -> never\n\n## A frame as the compiler described it under `--debug`: the function's name and\n## source, then `count` locals laid out after it.\nextern struct Shape:\n    name: str\n    source: str\n    count: u64\n\nextern struct Local:\n    name: str\n    kind: str\n    offset: u64\n    size: u64\n\nstruct Activation:\n    var shape: Shape*\?\n    var frame: void*\?\n    var line: u32\n\nstruct Break:\n    var file: str\n    var line: u32\n\nvar activations: Activation[512]\nvar depth: usize\nvar checked: bool\nvar active: bool\nvar started: bool\nvar stepping: bool\nvar step_over: usize\nvar breaks: Break[32]\nvar break_count: usize\nvar names: u8[4096]\nvar names_used: usize\nvar line_bytes: u8[512]\n\n## Called at every function entry and exit of a `--debug` build.\npub func enter(shape: void*):\n    if depth < activations.length:\n        activations[depth] = Activation(shape = (Shape*)shape, frame = none, line = 0)\n    depth += 1\n\npub func leave():\n    if depth > 0:\n        depth -= 1\n\n## Called before every statement: stop when a breakpoint, a step, or the start asks.\npub func at(shape: void*, line: u32, frame: void*):\n    if not checked:\n        checked = true\n        active = getenv(\"LUCE_DEBUG\") != none\n    if not active or depth == 0 or depth > activations.length:\n        return\n    let top = depth - 1\n    let s = (Shape*)shape\n    activations[top] = Activation(shape = s, frame = frame, line = line)\n    var stop = false\n    if not started:\n        started = true\n        stop = true\n    elif stepping:\n        stop = true\n    elif step_over > 0 and depth <= step_over:\n        stop = true\n    elif hits(s.source, line):\n        stop = true\n    if not stop:\n        return\n    stepping = false\n    step_over = 0\n    print(f\"stopped at {s.source}:{line} in {s.name}\")\n    prompt(top)\n\nfunc hits(file: str, line: u32) -> bool:\n    var i: usize = 0\n    while i < break_count:\n        let b = breaks[i]\n        if b.line == line and (b.file == file or ends_with(file, b.file)):\n            return true\n        i += 1\n    return false\n\nfunc ends_with(text: str, suffix: str) -> bool:\n    if suffix.length > text.length:\n        return false\n    return (str)text.bytes[text.length - suffix.length..] == suffix\n\n## Read commands until one lets the program run.\nfunc prompt(top: usize):\n    while true:\n        let line = read_line() else return\n        let command = first_word(line)\n        let rest = trim((str)line.bytes[command.length..])\n        if command == \"r\" or command == \"run\" or command == \"c\" or command == \"continue\":\n            return\n        if command == \"s\" or command == \"step\":\n            stepping = true\n            return\n        if command == \"n\" or command == \"next\":\n            step_over = depth\n            return\n        if command == \"q\" or command == \"quit\":\n            print(\"quit\")\n            c_exit(0)\n        if command == \"b\" or command == \"break\":\n            add_break(rest)\n        elif command == \"p\" or command == \"print\":\n            show_named(top, rest)\n        elif command == \"locals\":\n            show_all(top)\n        elif command == \"bt\" or command == \"backtrace\":\n            backtrace()\n        elif command.length == 0:\n            continue\n        else:\n            print(f\"unknown command `{command}`; commands: break FILE:LINE, run, step, next, print NAME, locals, backtrace, quit\")\n\nfunc add_break(spec: str):\n    var colon: usize = spec.length\n    var i = spec.length\n    while i > 0:\n        i -= 1\n        if spec.bytes[i] == ':':\n            colon = i\n            break\n    if colon == spec.length:\n        print(\"break needs FILE:LINE\")\n        return\n    let file = (str)spec.bytes[..<colon]\n    let number = parse_line((str)spec.bytes[colon + 1..])\n    if number == 0 or break_count == breaks.length or names_used + file.length > names.length:\n        print(\"cannot set that breakpoint\")\n        return\n    memory.copy(names[names_used..], file.bytes, file.length)\n    let kept = (str)names[names_used..<names_used + file.length]\n    names_used += file.length\n    breaks[break_count] = Break(file = kept, line = number)\n    break_count += 1\n    print(f\"breakpoint {break_count} at {file}:{number}\")\n\nfunc parse_line(text: str) -> u32:\n    var value: u32 = 0\n    for byte in text.bytes:\n        if byte < '0' or byte > '9':\n            return 0\n        value = value * 10 + (u32)(byte - '0')\n    return value\n\nfunc backtrace():\n    var i = depth\n    var index: usize = 0\n    while i > 0:\n        i -= 1\n        let a = activations[i]\n        if let s = a.shape:\n            print(f\"#{index} {s.name} at {s.source}:{a.line}\")\n        index += 1\n\nfunc show_all(top: usize):\n    let a = activations[top]\n    let s = a.shape else return\n    var i: u64 = 0\n    while i < s.count:\n        show(local_of(s, i), a.frame)\n        i += 1\n\nfunc show_named(top: usize, name: str):\n    let a = activations[top]\n    let s = a.shape else return\n    var i: u64 = 0\n    while i < s.count:\n        let described = local_of(s, i)\n        if described.name == name:\n            show(described, a.frame)\n            return\n        i += 1\n    print(f\"no local named `{name}`\")\n\n## The locals follow the shape, each `sizeof(Local)` bytes.\nfunc local_of(s: Shape*, index: u64) -> Local*:\n    let base = (usize)s + sizeof(Shape) + (usize)index * sizeof(Local)\n    return (Local*)base\n\n## A local's value read from the frame and shown by its type's spelling.\nfunc show(described: Local*, frame: void*\?):\n    let f = frame else return\n    let address = (void*)((usize)f - (usize)described.offset)\n    let kind = described.kind\n    if kind == \"i64\" or kind == \"isize\":\n        print(f\"{described.name}: {kind} = {memory.read[i64](address)}\")\n    elif kind == \"i32\":\n        print(f\"{described.name}: {kind} = {memory.read[i32](address)}\")\n    elif kind == \"i16\":\n        print(f\"{described.name}: {kind} = {memory.read[i16](address)}\")\n    elif kind == \"i8\":\n        print(f\"{described.name}: {kind} = {memory.read[i8](address)}\")\n    elif kind == \"u64\" or kind == \"usize\":\n        print(f\"{described.name}: {kind} = {memory.read[u64](address)}\")\n    elif kind == \"u32\" or kind == \"char\":\n        print(f\"{described.name}: {kind} = {memory.read[u32](address)}\")\n    elif kind == \"u16\":\n        print(f\"{described.name}: {kind} = {memory.read[u16](address)}\")\n    elif kind == \"u8\":\n        print(f\"{described.name}: {kind} = {memory.read[u8](address)}\")\n    elif kind == \"bool\":\n        print(f\"{described.name}: {kind} = {memory.read[bool](address)}\")\n    elif kind == \"f64\":\n        print(f\"{described.name}: {kind} = {memory.read[f64](address)}\")\n    elif kind == \"f32\":\n        print(f\"{described.name}: {kind} = {memory.read[f32](address)}\")\n    elif kind == \"str\":\n        let text = memory.read[str](address)\n        print(f\"{described.name}: {kind} = \\\"{text}\\\"\")\n    elif kind == \"c.str\":\n        let text = memory.read[c.str](address)\n        print(f\"{described.name}: {kind} = \\\"{(str)text}\\\"\")\n    elif ends_with(kind, \"*\") or ends_with(kind, \"*\?\"):\n        print(f\"{described.name}: {kind} = 0x{hex(memory.read[usize](address))}\")\n    else:\n        var shown: usize = (usize)described.size\n        if shown > 32:\n            shown = 32\n        var text: u8[160]\n        var used: usize = 0\n        var i: usize = 0\n        while i < shown:\n            let byte = memory.read[u8]((void*)((usize)address + i))\n            let digits = \"0123456789abcdef\".bytes\n            text[used] = digits[(usize)(byte >> 4)]\n            text[used + 1] = digits[(usize)(byte & 15)]\n            text[used + 2] = ' '\n            used += 3\n            i += 1\n        print(f\"{described.name}: {kind} = {described.size} bytes {(str)text[..<used]}\")\n\nfunc first_word(line: str) -> str:\n    var i: usize = 0\n    while i < line.length and line.bytes[i] != ' ':\n        i += 1\n    return (str)line.bytes[..<i]\n\nfunc trim(text: str) -> str:\n    var start: usize = 0\n    var end = text.length\n    while start < end and text.bytes[start] == ' ':\n        start += 1\n    while end > start and (text.bytes[end - 1] == ' ' or text.bytes[end - 1] == '\\r'):\n        end -= 1\n    return (str)text.bytes[start..<end]\n\n## One line from standard input, without its newline; none at the end of input.\nfunc read_line() -> str\?:\n    var used: usize = 0\n    while used < line_bytes.length:\n        var byte: u8[1]\n        let n = c_read(0, &byte[0], 1)\n        if n <= 0:\n            if used == 0:\n                return none\n            break\n        if byte[0] == '\\n':\n            break\n        line_bytes[used] = byte[0]\n        used += 1\n    return (str)line_bytes[..<used]\n", 8765})})}});
